  assert.deepEqual([1, 4, 9].map(n => f('wh.wal', n, {n, d: '2022-11'})), ['1 portfel · lista giełdy z 2022-11', '4 portfele · lista giełdy z 2022-11', '9 portfeli · lista giełdy z 2022-11']);
