  assert.ok(E.ja['snb.wyk'].includes('最低値') && !E.ja['snb.wyk'].includes('最安値') && E.ru['snb.wyk'].startsWith('Отечественные банки'), 'v219: ja 最低値, ru jak reszta panelu');
