  const g2 = pgEnv({GLIVE: Object.assign({}, GL), gst: {period: '1T'}, GBACK: {'1D': 0, '1T': 0, '1M': 1, '1Q': 3, '1R': 12}, GDATA: {'1T': {eur: [1, 1, true], jpn: [0, 0, false], usa: [0, 0, false], rus: [0, 0, false]}}});
  g2.f.renderAssets();
