  assert.ok(el.innerHTML.includes('<div class="k-val" title="a&lt;b">F153718</div>') && el.innerHTML.includes('g.cov.of{"n":11,"m":12} · SZAC · 2026-10-06 · age(2026-10-06)'), el.innerHTML);
