  const f = new Function('t', 'gfmt', 'engDate', 'instRow', 'instFoot', 'engNum', 'escH', 'KR', html.slice(a0, a1) + '\nreturn stcPanel;')(
    (k, o) => k + (o ? JSON.stringify(o) : ''), v => v.toFixed(2) + ' mld', s => String(s), (a, b, c, d) => `[${a}|${b}|${d}]`, s => s, v => String(v), s => String(s), {data: {at: 'x'}});
