  assert.deepEqual([w(21, 33, 2), w(15, 40, 7), w(12, 23, 5)], ['na', 'na', 'na'], 'liczby z audytu: świat 21/33 (2 sesje), krypto od startu 15/40 (7 dni), okno 12/23 (5 dni)');
