test('v297g: słownik su297g — czysty JSON w 10 językach zaraz po poprzednim, te same klucze i pola {x}, tłumaczenia różne od angielskiego, bez nazw dostawców; każdy klucz użyty; zmienione teksty su295g we wszystkich językach', () => {
  const a = html.indexOf('{"pl":{"su297g.'); assert.ok(a > 0, 'słownik v297g');
  const d0 = html.lastIndexOf('const EXTRA', a), name = html.slice(d0 + 6, a - 1), n = +name.slice(5);
  assert.ok(html.slice(0, d0).endsWith('for(const l in EXTRA' + (n - 1) + ')if(I18N[l])Object.assign(I18N[l],EXTRA' + (n - 1) + '[l]);\n'), 'zaraz po linii nakładania poprzedniego słownika');
  const d1 = html.indexOf(';\nfor(const l in ' + name + ')if(I18N[l])Object.assign(I18N[l],' + name + '[l]);', a); assert.ok(d1 > a, 'linia nakładania');
  const D = JSON.parse(html.slice(a, d1)), L10 = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'], ph = s => (s.match(/\{\w+\}/g) || []).sort().join(',');
  assert.deepEqual(Object.keys(D), L10); const K = Object.keys(D.pl);
  assert.equal(K.length, 11); assert.ok(K.every(k => k.startsWith('su297g.')), K.join(','));
  for (const l of L10) { assert.deepEqual(Object.keys(D[l]), K, l); for (const k of K) { assert.ok(D[l][k].trim(), l + ' ' + k); assert.equal(ph(D[l][k]), ph(D.pl[k]), l + ' ' + k); assert.equal(v96src.I18N[l][k], D[l][k], 'scalony: ' + l + ' ' + k); } }
  for (const l of L10.slice(2)) for (const k of K) if (/[A-Za-z]{4}/.test(D.en[k].replace(/\{\w+\}/g, ' '))) assert.notEqual(D[l][k], D.en[k], l + ' ' + k);
  const names = G126_NAMES.HIDE.concat(G126_NAMES.BOTH);
  for (const l of L10) for (const k of K) for (const [nm, re] of names) assert.ok(!re.test(D[l][k]), l + ' ' + k + ': ' + nm);
  const b = su295.blk;
  for (const k of K) assert.ok(b.includes("'" + k + "'") || (k.startsWith('su297g.pt.') && b.includes("t('su297g.pt.'+p)")), 'klucz w kodzie: ' + k);
  /* zmienione teksty v295g: we wszystkich 10 językach nowe pole / nowy podpis */
  for (const l of L10) { const I = v96src.I18N[l];
    assert.ok(I['su295g.err'].includes('{p}') && I['su295g.live'].includes('{a}') && I['su295g.live'].includes('{h}'), l + ': err / live');
    assert.ok(!/\b(teraz|now|jetzt|ahora|maintenant|ora|agora|сейчас)\b|当前|現在/.test(I['su295g.live']), l + ': bez „teraz”'); }
  assert.deepEqual(L10.map(l => v96src.I18N[l]['su295g.k.brent']), ['Ropa Brent (dostawa fizyczna)', 'Brent crude (physical delivery)', 'Rohöl Brent (physische Lieferung)', 'Crudo Brent (entrega física)',
    'Brut Brent (livraison physique)', 'Greggio Brent (consegna fisica)', 'Petróleo Brent (entrega física)', 'Нефть Brent (физическая поставка)', '布伦特原油（实物交割）', 'ブレント原油（現物受け渡し）']);
  for (const l of L10) assert.equal(v96src.I18N[l]['usa.brent'], v96src.I18N[l]['su295g.k.brent'], l + ': podpis Brenta w panelu USA = podpis kafla surowców (ta sama seria)');
  assert.ok(html.includes("px('brent','usa.brent',oil,'usa.u.bbl')") && !html.includes('Morze Północne') && !html.includes('(North Sea)'), 'stary podpis usunięty we wszystkich słownikach');
  assert.ok(html.includes('#g-surowce .su-k>small.su-qr{color:var(--yl-tx)}') && html.includes('#g-usa .etfk>small.su-qr{'), 'styl uwagi');
});


/* ===================== v297c: ZŁOTO I SUROWCE A KRYPTO — runda 2 recenzji: uczciwy opis zmiany podaży tokenów złota (w obiegu, netto; część kapitału
   może pochodzić spoza krypto), granica „<0,005 t” (kafel i zdanie), korelacja z S&P 500 „—” z powodem, kafel premii z ceną tokenu z pomiaru
   (prem_px) i „—” zamiast „0,00”. Zegar przypięty w zk295c.run (2026-10-07T20:20Z). */
test('v297c: tokeny złota — zmiana podaży opisana uczciwie (w obiegu, netto: wprowadzone do obiegu minus wycofane; nie wiadomo, skąd przyszedł kapitał — część może pochodzić spoza krypto) w 10 językach, bez wniosku „z krypto do złota”', () => {
  const {D} = zk295c.dict(), sp = zk295c.sp, L10 = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'];
  const SPOZA = {pl: 'spoza krypto', en: 'outside crypto', de: 'außerhalb des Kryptomarkts', es: 'fuera de las cripto', fr: 'en dehors de la crypto', it: 'fuori delle cripto', pt: 'fora das cripto', ru: 'не из криптовалют', zh: '加密货币之外', ja: '暗号資産の外'};
  const NETTO = {pl: 'netto', en: 'net', de: 'netto', es: 'netos', fr: 'nette', it: 'nett', pt: 'líquidos', ru: 'нетто', zh: '净', ja: '差し引き'};
  const OBIEG = {pl: 'w obiegu', en: 'in circulation', de: 'im Umlauf', es: 'en circulación', fr: 'en circulation', it: 'in circolazione', pt: 'em circulação', ru: 'в обращении', zh: '流通中', ja: '流通している'};
  /* brzmienie sprzed rundy 2 (wniosek o przepływie kapitału podany jak fakt) i „wybite minus spalone” (dla XAUT nieścisłe: obieg rośnie też, gdy emitent
     wydaje tokeny z rezerwy) — nie mogą wrócić w żadnym języku */
  const STARE = ['tyle kapitału trafiło do złota', 'tyle kapitału wyszło ze złota', 'z krypto przeszło', 'that much capital went into', 'that much capital left', 'so viel Kapital floss', 'so viel Kapital verließ',
    'ese capital entró', 'ese capital salió', 'autant de capital est entré', 'autant de capital a quitté', 'tanto capitale è entrato', 'tanto capitale è uscito', 'esse capital entrou', 'esse capital saiu',
    'столько капитала пришло', 'столько капитала ушло', '这么多资本流入了', '这么多资本离开了', 'その分の資本がトークン化された金に入りました', 'その分の資本がトークン化された金から出ました',
    'wybite minus spalone', 'wybito więcej, niż spalono', 'spalono więcej, niż wybito', 'minted minus tokens burned', 'more tokens were minted than burned', 'more tokens were burned than minted'];
  const F2 = zk295c.clone(ZK295C_FILE); F2.tok.razem.c30 = {oz: -321.507466, t: -0.01, usd: -1318250, od: '2026-09-07', do: '2026-10-07'};
  for (const L of L10) {
    for (const k of ['su295c.tok.in', 'su295c.not3']) assert.ok(D[L][k].includes(SPOZA[L]), L + ' ' + k + ': część może pochodzić spoza krypto — ' + D[L][k]);
    for (const k of ['su295c.tok.in', 'su295c.tok.out']) {
      assert.ok(D[L][k].includes(NETTO[L]), L + ' ' + k + ': zmiana netto — ' + D[L][k]);
      assert.ok(D[L][k].includes(OBIEG[L]), L + ' ' + k + ': podaż w obiegu (XAUT bez rezerwy emitenta) — ' + D[L][k]);
    }
    assert.ok(D[L]['su295c.tok.sub'].includes(L === 'ja' ? '流通' : OBIEG[L].replace(/^(w |in |im |en |em |в )/, '')) && /XAUT/.test(D[L]['su295c.tok.sub']), L + ' tok.sub: podaż w obiegu, XAUT bez rezerwy — ' + D[L]['su295c.tok.sub']);
    for (const h of [zk295c.run(ZK295C_FILE, {lang: L}).el.innerHTML, zk295c.run(F2, {lang: L}).el.innerHTML]) {
      for (const s of STARE) assert.ok(!h.includes(s), L + ': stare brzmienie „' + s + '”');
      assert.ok(!/su295c\./.test(h), L + ': surowy klucz');
    }
  }
  /* recenzja v297c: po włosku „al netto di X”, po francusku „net de X” znaczy zwykle „po odjęciu X” */
  for (const k of ['su295c.tok.in', 'su295c.tok.out']) { assert.ok(!/al netto d/.test(D.it[k]), 'it ' + k + ': ' + D.it[k]); assert.ok(!/\bnet de\b/.test(D.fr[k]), 'fr ' + k + ': ' + D.fr[k]); }
  assert.ok(D.it['su295c.tok.in'].includes('ha registrato un aumento netto di {v}') && D.it['su295c.tok.out'].includes('ha registrato una diminuzione netta di {v}'), 'it: aumento / diminuzione netta');
  assert.ok(D.fr['su295c.tok.in'].includes('a enregistré une hausse nette de {v}') && D.fr['su295c.tok.out'].includes('a enregistré une baisse nette de {v}'), 'fr: hausse / baisse nette');
  const h = sp(zk295c.run(ZK295C_FILE).el.innerHTML), T = ZK295C_FILE.tok;
  assert.ok(h.includes(`Oba tokeny razem: 35,64 t. W ciągu 30 dni (od 07.09.2026) podaż tokenów złota w obiegu wzrosła netto o 0,11 t (≈ 15 mln USD): o tyle więcej tokenów wprowadzono do obiegu, niż z niego wycofano. Nie wiadomo, skąd przyszedł ten kapitał — tokeny wydaje się za zwykłe dolary albo za krypto, więc część może pochodzić spoza krypto.`), 'napływ: ' + zk295c.txt(h).slice(0, 1200));
  assert.equal(T.razem.c30.t, 0.1134);
  assert.ok(h.includes('1 token = 1 uncja trojańska złota w sztabie u emitenta. Podaż to tokeny w obiegu (przy XAUT bez tokenów, które emitent trzyma jeszcze w rezerwie), w tonach: uncje ÷ 32 150,7466. Zmiana podaży to tokeny wprowadzone do obiegu minus wycofane z obiegu (netto).'), 'tok.sub: ' + zk295c.txt(h).slice(0, 1200));
  assert.ok(h.includes('Zmiana podaży tokenów złota to tokeny wprowadzone do obiegu minus wycofane (netto) i nie mówi, skąd przyszły pieniądze.') && h.includes('wzrost podaży nie dowodzi przepływu z krypto do złota — część może pochodzić spoza krypto.'), 'notatka not3');
  const g = sp(zk295c.run(F2).el.innerHTML);
  assert.ok(g.includes('W ciągu 30 dni (od 07.09.2026) podaż tokenów złota w obiegu spadła netto o 0,01 t (≈ 1,3 mln USD): o tyle więcej tokenów wycofano z obiegu, niż do niego wprowadzono. Nie wiadomo, dokąd trafił ten kapitał — do dolarów, do krypto czy do złota w sztabach.'), 'odpływ: ' + zk295c.txt(g).slice(0, 1200));
  const e = sp(zk295c.run(ZK295C_FILE, {lang: 'en'}).el.innerHTML);
  assert.ok(e.includes('Over 30 days (since 09/07/2026) the supply of gold tokens in circulation rose by a net 0.11 t (≈ 15 M USD): that many more tokens were put into circulation than were withdrawn from it. Where this capital came from is unknown'), 'en: ' + zk295c.txt(e).slice(0, 1200));
});

test('v297c: zmiana podaży mniejsza niż 0,005 t — „<0,005 t” na kaflu i „mniej niż 0,005 t” w zdaniu (ta sama granica; dokładnie −0,005 t to już 0,01 t), „się nie zmieniła” tylko przy zerze', () => {
  const {K} = zk295c.run(ZK295C_FILE), sp = zk295c.sp;
  assert.equal(sp(K.zkTon(-0.004, true)), '−<0,005 t'); assert.equal(sp(K.zkTon(0.0049, true)), '+<0,005 t'); assert.equal(sp(K.zkTon(0.0001)), '<0,005 t');
  assert.equal(sp(K.zkTon(0.005, true)), '+0,01 t'); assert.equal(sp(K.zkTon(-0.005, true)), '−0,01 t'); assert.equal(sp(K.zkTon(0, true)), '0,00 t');
  const F = zk295c.clone(ZK295C_FILE);
  F.tok.razem.c30 = {oz: 157.5, t: 0.0049, usd: 647000, od: '2026-09-07', do: '2026-10-07'};
  let h = sp(zk295c.run(F).el.innerHTML);
  assert.ok(h.includes('W ciągu 30 dni (od 07.09.2026) podaż tokenów złota zmieniła się tylko o +158 uncji (mniej niż 0,005 t; ≈ +0,6 mln USD).'), '0,0049 t: ' + zk295c.txt(h).slice(0, 1200));
  F.tok.razem.c30 = {oz: 1.2, t: 0, usd: 4920, od: '2026-09-07', do: '2026-10-07'};
  h = sp(zk295c.run(F).el.innerHTML);
  assert.ok(h.includes('podaż tokenów złota zmieniła się tylko o +1 uncji (mniej niż 0,005 t; ≈ +<0,1 mln USD).'), 'zmiana 1,2 uncji (0,0000 t po zaokrągleniu) — nie „0,00 t” ani „nie zmieniła się”: ' + zk295c.txt(h).slice(0, 1200));
  F.tok.razem.c30 = {oz: -160.7537, t: -0.005, usd: -659000, od: '2026-09-07', do: '2026-10-07'};
  h = sp(zk295c.run(F).el.innerHTML);
  assert.ok(h.includes('W ciągu 30 dni (od 07.09.2026) podaż tokenów złota w obiegu spadła netto o 0,01 t (≈ 0,7 mln USD)') && !h.includes('tylko o'), 'dokładnie −0,005 t: zdanie jak kafel (0,01 t), nie „mniej niż” — ' + zk295c.txt(h).slice(0, 1200));
  F.tok.XAUT.c7 = {oz: -128.6, t: -0.004, usd: -527000, od: '2026-09-30', do: '2026-10-07'};
  h = sp(zk295c.run(F).el.innerHTML);
  assert.ok(h.includes('<small class="neg">7 dni: −<0,005 t (≈ −0,5 mln USD) od 30.09.26</small>'), 'kafel: „<0,005 t” ze znakiem — ' + zk295c.txt(h).slice(0, 1200));   /* v322 (pkt 5): kolor znaku jak w tekście (dawniej bez koloru — zero po zaokrągleniu) */
  F.tok.razem.c30 = {oz: 0, t: 0, usd: 0, od: '2026-09-07', do: '2026-10-07'};
  h = sp(zk295c.run(F).el.innerHTML);
  assert.ok(h.includes('W ciągu 30 dni (od 07.09.2026) podaż tokenów złota się nie zmieniła.') && !h.includes('tylko o') && !h.includes('mniej niż 0,005 t'), 'zero — „się nie zmieniła”');
  F.tok.razem.c30 = {oz: 157.5, t: 0.0049, usd: 647000, od: '2026-09-07', do: '2026-10-07'};
  assert.ok(sp(zk295c.run(F, {lang: 'en'}).el.innerHTML).includes('changed by only +158 ounces (less than 0.005 t; ≈ +0.6 M USD).'), 'en: „less than 0.005 t”');
});

test('v297c: korelacja z S&P 500 — ten sam opis co złoto i ropa: za mało wspólnych dni = „—” z powodem i dniem końca okna, bez linii (nie zero)', () => {
  const {K} = zk295c.run(ZK295C_FILE), sp = zk295c.sp;
  const F = zk295c.clone(ZK295C_FILE); F.kor.sp = {v: null, n: 59, d: '2026-10-05', s: []};
  const g = sp(K.zkKor(F));
  assert.ok(g.includes('z S&amp;P 500 (akcje USA) <b>—</b><small>za mało wspólnych dni (59, potrzeba 60) · okno do 05.10.26, 59 wspólnych dni</small>'), 'S&P 500 „—”: ' + zk295c.txt(g));
  assert.ok(g.includes('<polyline class="arc-l zk-au"') && !g.includes('<polyline class="arc-l zk-sp"'), 'bez punktów S&P 500 — bez linii');
  assert.ok(g.includes(`ze złotem <b>${K.zkKorTxt(ZK295C_FILE.kor.zl.v)}</b>`), 'złoto bez zmian');
  F.kor.sp = {v: 0.41, n: 90, d: '2026-10-06', s: [['2026-10-05', 0.4], ['2026-10-06', 0.41]]};
  assert.ok(sp(K.zkKor(F)).includes('z S&amp;P 500 (akcje USA) <b>+0,41</b><small>umiarkowanie w tę samą stronę · okno do 06.10.26, 90 wspólnych dni</small>'), 'S&P 500 z liczbą');
});

test('v297c: kafel premii — cena tokenu Z POMIARU premii (prem_px, ta sama chwila co premia), nie nowsza cena tokenu; brak ceny tokenu lub różnicy chwil = „—”, nigdy „0,00” ani „0 min” (10 języków)', () => {
  const {D} = zk295c.dict(), sp = zk295c.sp, P = ZK295C_FILE.tok.PAXG, X = ZK295C_FILE.tok.XAUT;
  assert.deepEqual([P.prem_px, P.px, P.prem_at, P.px_at, X.prem_px], [4114.84, 4114.84, '2026-10-07T20:13:00+00:00', '2026-10-07T20:13:00+00:00', 4106.66], 'plik jak wynik zbieracza: pomiar z tą samą ceną tokenu');
  const kafel = (h, L) => { const lab = D[L]['su295c.p.paxg'], i = h.indexOf(lab + '</span>'); assert.ok(i > 0, L + ': kafel premii PAXG'); return h.slice(i, h.indexOf('<div class="etfk">', i)); };
  /* recenzja v297c (weekend): nowa cena tokenu 4150 z 23:13 bez ceny złota z ostatniej godziny — pomiar z 20:13 zostaje z JEGO ceną tokenu */
  const F = zk295c.clone(ZK295C_FILE); Object.assign(F.tok.PAXG, {px: 4150, px_at: '2026-10-07T23:13:00+00:00'});
  const h = sp(zk295c.run(F, {now: '2026-10-07T23:20:00Z'}).el.innerHTML);
  assert.ok(h.includes('PAXG — premia do ceny złota</span><b class="pos">+0,05%<small>token 4114,84 USD, złoto 4113,00 USD (notowanie godzinowe; różnica chwil 13 min)</small></b><small class="mtxt">pomiar: [2026-10-07T20:13:00+00:00]'), 'cena tokenu z chwili pomiaru: ' + zk295c.txt(h).slice(0, 900));   /* v322 (pkt 5): premia w kolorze znaku */
  assert.ok(!h.includes('4150,00') && !kafel(h, 'pl').includes('4150'), 'nowsza cena tokenu nie trafia na kafel premii');
  /* brak ceny tokenu z pomiaru (plik bez pola, null, tekst) i brak różnicy chwil — „—” w każdym języku, nigdy „0,00” / „0 min” */
  for (const brak of [{prem_px: null}, {prem_px: undefined}, {prem_px: 'x'}, {prem_px: NaN}]) {
    const G = zk295c.clone(ZK295C_FILE); Object.assign(G.tok.PAXG, {px: null, dt_min: null}); if (brak.prem_px === undefined) delete G.tok.PAXG.prem_px; else G.tok.PAXG.prem_px = brak.prem_px;
    for (const L of ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja']) {
      const k = sp(kafel(sp(zk295c.run(G, {lang: L}).el.innerHTML), L)), tpl = sp(D[L]['su295c.p.px']), pp = tpl.split('{p}'), mm = tpl.split('{m}');
      assert.ok(k.includes(pp[0] + '—' + pp[1].slice(0, 4)), L + ' ' + JSON.stringify(brak) + ': cena tokenu „—” — ' + zk295c.txt(k));
      assert.ok(k.includes('—' + mm[1].slice(0, 3)), L + ': różnica chwil „—” — ' + zk295c.txt(k));
      assert.ok(!/(?<![\d.,\s])0[.,]00(?!\d)/.test(k), L + ': bez „0,00” — ' + zk295c.txt(k));
      assert.ok(k.includes('4113') || k.includes('4,113') || k.includes('4.113') || k.includes('4 113'), L + ': cena złota z pomiaru zostaje');
    }
  }
  const pl = sp(kafel(sp(zk295c.run(ZK295C_FILE).el.innerHTML), 'pl'));
  assert.ok(pl.includes('token 4114,84 USD, złoto 4113,00 USD (notowanie godzinowe; różnica chwil 13 min)'), 'plik z pomiarem — jak dotąd');
  const G = zk295c.clone(ZK295C_FILE); G.tok.PAXG.prem_px = null; G.tok.PAXG.dt_min = null;
  assert.ok(sp(kafel(sp(zk295c.run(G).el.innerHTML), 'pl')).includes('token — USD, złoto 4113,00 USD (notowanie godzinowe; różnica chwil — min)'), 'pl: „—” zamiast „0,00” i „0 min”');
});

