  const B = su298.blk(su298.sp(K.el.innerHTML), 'su-b-fiz'), d = x => su298.day('pl', x);
  const T = id => { const i = B.indexOf(`data-su3="${id}"`); return B.slice(i, B.indexOf('</div>', i)); };
