/* strażnik tłumaczeń v142 (kategoria c — nazwa własna pisana w tym języku tak samo jak po angielsku): Bosporus (de) */
Object.assign(V142_OK, {'sz305.k.bosfor': 'de'});
const sz305 = (() => {
  const cut = (a, b) => { const i = html.indexOf(a), j = html.indexOf(b, i); assert.ok(i > 0 && j > i, 'wycinek: ' + a); return html.slice(i, j); };
  const arc = cut('function arcMs(d){', '\n/* v293 (audyt G2)'), wk = cut('const wkNum=v=>', '\n/* pierścień: udziały'), wk2 = cut('const wkMs=d=>', '\nconst WK_FGZ=');
  const blk = cut('/* ===================== v295g: SUROWCE', '\nsuLoad();suAuto();'), code = cut('/* ===================== v305g: SZLAKI', '/* ---------- panel ---------- */');
  const lis = cut('/* v305g: szlaki handlowe — plik data/szlaki.json', '\n/* ===================== v98: USA — energia');
  const l0 = html.indexOf('const LOCALE='), LOC = new Function(html.slice(l0, html.indexOf('\n', l0)) + '\nreturn LOCALE;')();
  const f0 = html.indexOf('const NF={};'), f1 = html.indexOf('\n', html.indexOf('const fPct=', f0));
  const NOW = Date.parse('2026-10-08T12:00:00Z');
  class FD extends Date { constructor(...a) { if (a.length === 0) super(NOW); else super(...a); } static now() { return NOW; } }
  const clone = o => JSON.parse(JSON.stringify(o)), sp = su295.sp, txt = su295.txt;
  const BODY = "'use strict';\n" + arc + '\n' + wk + '\n' + wk2 + '\n' + blk + '\n' + lis + '\nreturn {SU, SZ, renderSu, suApply, szLoad, szApply, szOk, szBlk, szZ, szT};';
  const mk = (L, files, opt) => {
    opt = opt || {};
    const F = new Function('LANG', 'LOCALE', html.slice(f0, f1) + '\nreturn {nfmt, sg, fPct};')(L, LOC);
    const el = {innerHTML: '', hidden: true, open: [], querySelectorAll(q) { return q === 'details[open]' ? this.open.map(id => ({id})) : []; }, querySelector() { return null; }};
    const calls = [], clicks = [], ivs = [];
    const srv = n => { calls.push(n); const v = (files || {})[n]; return {then(f) { f(v === undefined ? null : clone(v)); return this; }}; };
    const doc = {addEventListener: (e, f) => clicks.push([e, f]), querySelector: () => null, hidden: false};
    const api = new Function('$', 't', 'escH', 'nfmt', 'sg', 'fPct', 'LOCALE', 'LANG', 'gAgeNote', 'engDate', 'srvJSON', 'glyphImg', 'flagImg', 'flagsHtml', 'sepK', 'sepL',
      'localStorage', 'document', 'MutationObserver', 'setInterval', 'Date', 'renderUsa', BODY)(
      q => (q === '#g-surowce' ? el : null), v96src.tFor(L), v96src.escH, F.nfmt, F.sg, F.fPct, LOC, L, d => ' · wiek(' + d + ')', s => 'D:' + s, srv,
      v96src.H.glyphImg, v96src.H.flagImg, undefined, () => ': ', () => ', ', {getItem: () => null, setItem() {}}, doc,
      function () { this.observe = () => {}; }, (f, ms) => { ivs.push([f, ms]); return ivs.length; }, FD, undefined);
    return {api, el, calls, clicks, ivs, doc};
  };
  const files = F => ({surowce: SU295_FILE, szlaki: F === undefined ? SZ305_FILE : F});
  /* blok #su-b-sz (HTML do jego końca) i kafle cieśnin: id → fragment do następnego kafla */
  const blkOf = h => { const i = h.indexOf('<details class="etfd su-b sz-b" id="su-b-sz">'); return i < 0 ? '' : h.slice(i, h.indexOf('</details>', i) + 10); };
  const tiles = B => { const o = {}, M = [...B.matchAll(/<div class="etfk su-k sz-k" data-sz="(\w+)">/g)];
    M.forEach((m, i) => { o[m[1]] = B.slice(m.index, i + 1 < M.length ? M[i + 1].index : B.indexOf('</div><p class="pnote">', m.index) + 6); }); return o; };
  /* słuchacz kliknięć i zegar bloku (rozpoznane po kodzie — w tym samym miejscu bywają słuchacze innych bloków panelu) */
  const mine = f => String(f).includes('su-b-sz') || String(f).includes('szLoad');
  const ev = () => ({target: {closest: s => (s === '#g-surowce details#su-b-sz>summary' ? {} : null)}});
  const clk = K => { const C = K.clicks.filter(c => c[0] === 'click' && mine(c[1])); assert.equal(C.length, 1, 'jeden słuchacz bloku'); C[0][1](ev()); };
  const inne = K => K.clicks.filter(c => c[0] === 'click' && !mine(c[1])).forEach(([, f]) => f(ev()));
  const iv = K => { const I = K.ivs.filter(x => mine(x[0])); assert.equal(I.length, 1, 'jeden zegar bloku'); return I[0]; };
  /* blok po wczytaniu pliku (kliknięcie nagłówka) */
  const loaded = (L, F) => { const K = mk(L, files(F)); K.api.suApply(SU295_FILE); K.el.open = ['su-b-sz']; clk(K); return {K, B: blkOf(sp(K.el.innerHTML))}; };
  const day = (L, d) => su295.day(L, d), mon = (L, ym) => su295.mon(L, ym);
  const cols = h => { const i = h.indexOf('<div class="wk-ch wk-cols"'); if (i < 0) return []; const c = h.slice(i, h.indexOf('</svg>', i));
    return [...c.matchAll(/<rect class="wk-hit" x="[\d.]+" y="0" width="10" height="100" data-t="([^"]*)"\/>/g)].map(m => sp(m[1])); };
  const hits = h => { const i = h.indexOf('<div class="wk-ch wk-lines"'); if (i < 0) return []; const c = h.slice(i, h.indexOf('</svg>', i));
    return [...c.matchAll(/<rect class="wk-hit" [^>]*data-t="([^"]*)"\/>/g)].map(m => sp(m[1])); };
  return {mk, files, blkOf, tiles, clk, inne, iv, loaded, day, mon, cols, hits, clone, sp, txt, code, lis, NOW};
})();

test('v305g: blok „Szlaki handlowe i łańcuchy dostaw” — ostatni w panelu, przed stopką, zwinięty; plik dopiero po kliknięciu nagłówka (raz), nieudane pobranie bez pętli, kliknięcie = nowa próba', () => {
  const K = sz305.mk('pl', sz305.files()); K.api.suApply(SU295_FILE);
  let h = sz305.sp(K.el.innerHTML);
  const iB = h.indexOf('<details class="etfd su-b sz-b" id="su-b-sz">'), iF = h.indexOf('<p class="pfoot">');
  assert.ok(iB > 0 && iF > iB && h.lastIndexOf('<details') === iB, 'ostatni blok panelu, przed stopką');
  assert.ok(h.indexOf('<b>Co surowce mówią o gospodarce</b>') < iB, 'po blokach C (i D, gdy są)');
  assert.equal(sz305.blkOf(h), '<details class="etfd su-b sz-b" id="su-b-sz"><summary>Szlaki handlowe i łańcuchy dostaw</summary><p class="pnote">Wczytujemy dane…</p></details>');
  assert.deepEqual(K.calls, [], 'przy starcie i rysowaniu panelu — bez pobrania data/szlaki.json');
  assert.equal(html.split("srvJSON('szlaki')").length, 2, 'jedno miejsce pobrania (szLoad)');
  assert.ok(!/suLoad\(\)\{[^}]*szlaki/.test(html) && !html.includes("['oecd','rynki','ceny','kursy','dzis','krypto','cmc','szlaki']"), 'nie przy starcie strony');
  /* kliknięcie nagłówka bloku — słuchacz panelu (i innych bloków) nic nie pobiera, słuchacz bloku pobiera raz */
  assert.ok(K.clicks.filter(c => c[0] === 'click').length >= 2, 'słuchacz panelu + słuchacz bloku');
  sz305.inne(K); assert.deepEqual(K.calls, [], 'słuchacz panelu nie reaguje na blok szlaków');
  K.el.open = ['su-b-sz']; sz305.clk(K);
  assert.deepEqual(K.calls, ['szlaki']);
  h = sz305.sp(K.el.innerHTML);
  assert.ok(sz305.blkOf(h).includes('data-sz="ormuz"') && h.includes('<p class="pfoot">'), 'po wczytaniu — panel narysowany ponownie, blok z kaflami');
  sz305.clk(K); K.api.renderSu(); assert.deepEqual(K.calls, ['szlaki'], 'plik w pamięci — bez kolejnych pobrań');
  /* odświeżanie: co 30 min, tylko gdy plik był wczytany */
  assert.equal(sz305.iv(K)[1], 30 * 60 * 1000);
  sz305.iv(K)[0](); assert.deepEqual(K.calls, ['szlaki', 'szlaki'], 'po wczytaniu — odświeżenie');
  const K0 = sz305.mk('pl', sz305.files()); K0.api.suApply(SU295_FILE); sz305.iv(K0)[0]();
  assert.deepEqual(K0.calls, [], 'blok nigdy nierozwinięty — zegar nic nie pobiera');
  /* nieudane pobranie: zdanie z prośbą, bez pętli przy kolejnych rysowaniach; kliknięcie — nowa próba; potem dane */
  const F = {surowce: SU295_FILE}, K2 = sz305.mk('pl', F); K2.api.suApply(SU295_FILE); K2.el.open = ['su-b-sz']; sz305.clk(K2);
  assert.deepEqual(K2.calls, ['szlaki']);
  assert.ok(sz305.blkOf(sz305.sp(K2.el.innerHTML)).includes('<p class="pnote">Nie udało się wczytać danych — zwiń i rozwiń blok, aby spróbować ponownie.</p>'));
  K2.api.renderSu(); K2.api.renderSu(); assert.deepEqual(K2.calls, ['szlaki'], 'bez pętli');
  F.szlaki = SZ305_FILE; sz305.clk(K2); assert.deepEqual(K2.calls, ['szlaki', 'szlaki']);
  assert.ok(sz305.blkOf(sz305.sp(K2.el.innerHTML)).includes('data-sz="ormuz"'));
  /* chwilowy błąd po wczytaniu nie zasłania danych; plik innej wersji = błąd przy pierwszym wczytaniu */
  delete F.szlaki; sz305.iv(K2)[0](); assert.ok(sz305.blkOf(sz305.sp(K2.el.innerHTML)).includes('data-sz="ormuz"'));
  for (const bad of [Object.assign(sz305.clone(SZ305_FILE), {v: 2}), {v: 1, at: 'x', cies: {}}, {v: 1, at: '2026-10-08T04:30:00+00:00'}]) {
    const K3 = sz305.mk('pl', {surowce: SU295_FILE, szlaki: bad}); K3.api.suApply(SU295_FILE); sz305.clk(K3);
    assert.ok(sz305.blkOf(sz305.sp(K3.el.innerHTML)).includes('Nie udało się wczytać danych'), JSON.stringify(bad).slice(0, 60));
  }
  /* bez pliku surowców panel jest schowany — bloku nie ma */
  const K4 = sz305.mk('pl', sz305.files()); K4.api.suApply(null); assert.equal(K4.el.innerHTML, ''); assert.ok(K4.el.hidden);
});

test('v305g: kafle 8 cieśnin — statki dziennie (średnia 7 dni), zmiana rok do roku w kolorze kierunku, rok wcześniej, tankowce, ładunek (szacunek), mini-wykres, dni średniej i wiek; flagi krajów', () => {
  const {B} = sz305.loaded('pl'), T = sz305.tiles(B), d = x => sz305.day('pl', x);
  assert.deepEqual(Object.keys(T), ['ormuz', 'bab', 'suez', 'bosfor', 'panama', 'malakka', 'gibraltar', 'przyladek'], 'kolejność: Ormuz, Bab el-Mandeb, Suez, Bosfor, Panama, Malakka, Gibraltar, Przylądek');
  assert.ok(B.includes('<p class="wk-sub"><b>Ruch statków w cieśninach i kanałach</b></p><div class="etfkpis su-kpis sz-kpis">'), 'siatka pulsu (4 kolumny, telefon 2)');
  const O = T.ormuz;
  assert.ok(O.includes('Cieśnina Ormuz') && O.includes('img/flagi/ir.svg') && O.includes('img/flagi/om.svg'), 'nazwa i flagi krajów nad cieśniną');
  assert.ok(O.includes('<b>2,7 <small class="mtxt">statku dziennie</small> <small class="neg">▼ −97,6% rok do roku</small></b>'), O);
  assert.ok(O.includes('<small class="mtxt">rok wcześniej: 111,3 dziennie</small><small class="mtxt">w tym tankowce: 0,9 dziennie</small><small class="mtxt su-x">ładunek ≈ 0,08 mln t dziennie (szacunek)</small>'));
  assert.ok(O.includes('<div class="su-sp"><div class="arc-gr">') && O.includes('<polyline class="arc-l l1"'), 'mini-wykres (średnia 7 dni, 90 dni)');
  assert.ok(O.includes('<small class="mtxt su-d">średnia 7 dni: ' + d('2026-09-28') + ' – ' + d('2026-10-04') + ' · wiek(2026-10-04)</small>'), 'dni średniej i wiek ostatniego dnia');
  assert.ok(T.suez.includes('<b>43,1 ') && T.suez.includes('<small class="pos">▲ +4,9% rok do roku</small>') && T.suez.includes('img/flagi/eg.svg'));
  assert.ok(T.gibraltar.includes('<small class="neg">▼ −0,4% rok do roku</small>'), 'mała zmiana z jednym miejscem po przecinku');
  assert.ok(T.malakka.includes('<b>226,3 ') && T.malakka.includes('ładunek ≈ 8,70 mln t dziennie') && ['my', 'sg', 'id'].every(c => T.malakka.includes('img/flagi/' + c + '.svg')));
  assert.ok(T.bosfor.includes('▼ −61,9% rok do roku') && T.przyladek.includes('Przylądek Dobrej Nadziei') && T.przyladek.includes('img/flagi/za.svg'));
  assert.ok(B.includes('Liczba w kafelku to średnia z 7 ostatnich dni') && B.includes('Ładunek to szacunek z zanurzenia i nośności statków, nie pomiar.'), 'opis pomiaru i szacunku');
  assert.ok(B.includes(' Zmiana — wobec tych samych dni tygodnia rok wcześniej (' + d('2025-09-29') + ' – ' + d('2025-10-05') + ').</p>'), 'okno porównania z datami');
  /* braki: cieśnina bez danych — „—”; 0 statków — pomiar 0; rok wcześniej < 1 statku — bez %; bez roku wcześniej — „—”; bez tankowców i ładunku — bez linii */
  const F = sz305.clone(SZ305_FILE), K = F.cies.k;
  delete K.bab; K.ormuz.s7 = 0; K.ormuz.chg = -100; K.suez.r7 = 0.57; K.suez.chg = null; K.panama.r7 = null; K.panama.chg = null; K.panama.t7 = null; K.panama.c7 = null;
  K.bosfor.m7 = K.bosfor.m7.slice(-1);
  const T2 = sz305.tiles(sz305.loaded('pl', F).B);
  assert.ok(T2.bab.includes('<b class="na">—</b><small class="mtxt">brak danych — to nie zero</small>') && !/\d/.test(sz305.txt(T2.bab).replace('Bab el-Mandeb', '')), 'brak = „—”, nigdy zero');
  assert.ok(T2.ormuz.includes('<b>0,0 <small class="mtxt">statku dziennie</small> <small class="neg">▼ −100,0% rok do roku</small></b>'), '0 statków to pomiar');
  assert.ok(T2.suez.includes('<b>43,1 <small class="mtxt">statku dziennie</small></b><small class="mtxt">rok wcześniej: 0,6 dziennie</small>'), 'bez zmiany w %');
  assert.ok(T2.panama.includes('<small class="mtxt">rok wcześniej: —</small>') && !T2.panama.includes('tankowce') && !T2.panama.includes('ładunek'));
  assert.ok(!T2.bosfor.includes('su-sp') && T2.bosfor.includes('su-d'), 'jeden punkt średniej — bez wykresu, z datą');
});

test('v305g: światowy wskaźnik presji w łańcuchach dostaw — kolumny 36 miesięcy (jeden kolor), zdanie z poziomu i miesiącem poprzednim, miesiąc danych, wydanie i wiek', () => {
  const {B} = sz305.loaded('pl'), m = x => sz305.mon('pl', x);
  assert.ok(B.includes('<p class="wk-sub"><b>Światowy wskaźnik presji w łańcuchach dostaw</b> · od października 2023 · wydanie: ' + m('2026-10') + '</p>'), 'tytuł, początek i wydanie');
  const C = sz305.cols(B);
  assert.equal(C.length, 36); assert.equal(C[0], m('2023-10') + ': −0,37'); assert.equal(C[35], m('2026-09') + ': +1,28');
  const c0 = B.indexOf('<div class="wk-ch wk-cols"'), cc = B.slice(c0, B.indexOf('</svg>', c0));
  assert.ok(cc.includes('class="wk-b lvl"') && !cc.includes('wk-b pos') && !cc.includes('wk-b neg'), 'jeden kolor — większa presja to nie „zielone”');
  assert.ok(cc.includes('aria-label="Światowy wskaźnik presji w łańcuchach dostaw, kolumny miesięczne: 36"'));
  assert.ok(B.includes('<p class="pnote su-s">' + m('2026-09') + ' · wiek(2026-09): +1,28 — presja w światowych łańcuchach dostaw jest wyraźnie większa niż zwykle (miesiąc wcześniej +1,20).</p>'));
  assert.ok(B.includes('0 oznacza przeciętną presję (średnia od 1997 r.)') && B.includes('pokazujemy najnowsze wydanie'));
  const lv = v => { const F = sz305.clone(SZ305_FILE); F.presja.d[35][1] = v; const S = sz305.loaded('pl', F).B; const i = S.indexOf('<p class="pnote su-s">' + m('2026-09')); return sz305.txt(S.slice(i, S.indexOf('</p>', i))); };
  assert.ok(lv(0.5).includes(': +0,50 — presja w światowych łańcuchach dostaw jest nieco większa niż zwykle'));
  assert.ok(lv(0).includes(': 0,00 — presja w światowych łańcuchach dostaw jest przeciętna (miesiąc wcześniej +1,20)'), 'zero bez znaku');
  assert.ok(lv(-0.4).includes(': −0,40 — presja w światowych łańcuchach dostaw jest nieco mniejsza niż zwykle'));
  assert.ok(lv(-1.2).includes(': −1,20 — presja w światowych łańcuchach dostaw jest wyraźnie mniejsza niż zwykle'));
  const F = sz305.clone(SZ305_FILE); F.presja.d = [['2026-09', 1.28]]; delete F.presja.wyd;
  const S = sz305.loaded('pl', F).B;
  assert.ok(S.includes('· od września 2026</p>') && S.includes('(miesiąc wcześniej —)') && sz305.cols(S).length === 1, 'jeden miesiąc: bez wydania, poprzedni „—”');
});

test('v305g: indeks cen surowców — 4 linie od 100 (całość, energia, metale i minerały, rolne), zdanie: tydzień, poziom, zmiany w tygodniu i od początku wykresu, data i wiek', () => {
  const {B} = sz305.loaded('pl'), d = x => sz305.day('pl', x);
  assert.ok(B.includes('<p class="wk-sub"><b>Indeks cen surowców</b> · tygodniowo, start = 100 (' + d('2026-01-28') + ')</p>'));
  for (const c of ['s1', 's2', 'sz-m', 'sz-a']) assert.ok(B.includes('<polyline class="wk-l ' + c + '"'), 'linia ' + c);
  assert.ok(['Całość', 'Energia', 'Metale i minerały', 'Rolne'].every(n => B.includes('</i>' + n + '</span>')), 'legenda');
  const H = sz305.hits(B);
  assert.equal(H.length, 36);
  assert.equal(H[0], new Date(Date.parse('2026-01-28T12:00:00Z')).toLocaleDateString('pl-PL', {day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC'}) + ' · Całość: 100,0 · Energia: 100,0 · Metale i minerały: 100,0 · Rolne: 100,0');
  assert.ok(H[35].endsWith(' · Całość: 110,7 · Energia: 125,5 · Metale i minerały: 93,6 · Rolne: 102,6'), H[35]);
  assert.ok(B.includes('<p class="pnote su-s">Tydzień do ' + d('2026-09-30') + ' · wiek(2026-09-30): indeks cen surowców 729,3 pkt, zmiana w tygodniu −1,9% (energia −2,4%, metale i minerały −1,5%, rolne −1,6%); od ' + d('2026-01-28') + ': +10,7%.</p>'));
  assert.ok(B.includes('Wagi pochodzą z produkcji Kanady (dużo ropy i gazu), więc to przybliżenie cen surowców na świecie.') && B.includes('Ostatnie tygodnie są wstępne'), 'opis przybliżenia i danych wstępnych');
  /* seria z innym ostatnim tygodniem — „—” w zdaniu (nie zmiana z innego tygodnia); seria bez tygodnia startu — bez linii */
  const F = sz305.clone(SZ305_FILE); F.bcpi.s.energia.d.pop(); F.bcpi.s.rolne.d.shift();
  const S = sz305.loaded('pl', F).B;
  assert.ok(S.includes('(energia —, metale i minerały −1,5%, rolne −1,6%)') && !S.includes('<polyline class="wk-l sz-a"') && S.includes('<polyline class="wk-l s2"'));
});

test('v305g: błąd części — z danymi „pokazujemy wcześniejsze dane”, bez danych „jeszcze nie pobrano” (nazwy części); stopka bloku z czasem pliku', () => {
  const F = sz305.clone(SZ305_FILE); F.ok = {cies: false, presja: true, bcpi: false}; delete F.bcpi;
  const {B} = sz305.loaded('pl', F);
  assert.ok(B.includes('<p class="pnote neu">Ostatnie pobranie części danych się nie udało (ruch statków) — pokazujemy wcześniejsze dane z ich datą.</p>'));
  assert.ok(B.includes('<p class="pnote">Części danych jeszcze nie pobrano (indeks cen surowców) — pojawią się po pierwszym udanym pobraniu.</p>'));
  assert.ok(!B.includes('Indeks cen surowców</b>') && B.includes('data-sz="ormuz"'));
  assert.ok(B.includes('<p class="pnote">Plik z D:2026-10-08T04:30:00+00:00</p></details>'), 'czas pliku na końcu bloku');
  assert.ok(sz305.loaded('pl').B.startsWith('<details class="etfd su-b sz-b" id="su-b-sz"><summary>Szlaki handlowe i łańcuchy dostaw</summary><p class="pnote">Ile statków przepływa przez najważniejsze cieśniny i kanały świata'));
});

test('v305g: 10 języków — blok w języku widza, bez surowych kluczy i bez nazw wydawców; słownik sz305 czystym JSON-em, te same klucze i pola {x}, każdy klucz użyty w kodzie', () => {
  const L10 = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'];
  const PROV = /PortWatch|\bIMF\b|\bMFW\b|\bFMI\b|МВФ|New York|Nowego Jorku|Bank of Canada|Bank Kanady|Banque du Canada|Banco de Canad|\bBoC\b|GSCPI|BCPI|ArcGIS|Valet|\bFed\b|AIS\b/;
  const names = G126_NAMES.HIDE.concat(G126_NAMES.BOTH);
  for (const L of L10) {
    const B = sz305.loaded(L).B, T = sz305.txt(B);
    assert.ok(!B.includes('sz305.') && !B.includes('su295g.') && !B.includes('undefined') && !B.includes('NaN'), L + ': klucze i liczby');
    assert.ok(!PROV.test(T), L + ': nazwa wydawcy: ' + (T.match(PROV) || [])[0]);
    for (const [n, re] of names) assert.ok(!re.test(T), L + ': ' + n);
    assert.equal(Object.keys(sz305.tiles(B)).length, 8, L);
  }
  const E = sz305.loaded('en').B;
  assert.ok(E.includes('<summary>Trade routes and supply chains</summary>') && E.includes('Strait of Hormuz') && E.includes('<b>2.7 <small class="mtxt">ships a day</small> <small class="neg">▼ −97.6% year on year</small></b>'));
  /* słownik: szukany po kluczu (numer nadaje łatka przy nakładaniu) */
  const a = html.indexOf('{"pl":{"sz305.b":'); assert.ok(a > 0, 'słownik v305g');
  const d0 = html.lastIndexOf('const EXTRA', a), name = html.slice(d0 + 6, a - 1);
  const d1 = html.indexOf(';\nfor(const l in ' + name + ')if(I18N[l])Object.assign(I18N[l],' + name + '[l]);', a); assert.ok(d1 > a, 'linia nakładania zaraz po słowniku');
  assert.ok(/^EXTRA\d+$/.test(name) && html.split('const ' + name + '=').length === 2);
  const D = JSON.parse(html.slice(a, d1)), ph = s => (s.match(/\{\w+\}/g) || []).sort().join(',');
  assert.deepEqual(Object.keys(D), L10); const K = Object.keys(D.pl);
  assert.ok(K.length >= 40 && K.every(k => k.startsWith('sz305.')), 'klucze: ' + K.length);
  for (const l of L10) { assert.deepEqual(Object.keys(D[l]), K, l); for (const k of K) { assert.ok(D[l][k].trim(), l + ' ' + k); assert.equal(ph(D[l][k]), ph(D.pl[k]), l + ' ' + k); assert.equal(v96src.I18N[l][k], D[l][k], 'scalony: ' + l + ' ' + k); } }
  for (const l of L10.slice(2)) for (const k of K) if (/[A-Za-z]{4}/.test(D.en[k].replace(/\{\w+\}/g, ' ')) && !(V142_OK[k] || '').split(' ').includes(l)) assert.notEqual(D[l][k], D.en[k], l + ' ' + k);
  const c = sz305.code, ids = {k: ['ormuz', 'bab', 'suez', 'bosfor', 'panama', 'malakka', 'gibraltar', 'przyladek'], b: ['calosc', 'energia', 'metale', 'rolne'], pt: ['cies', 'presja', 'bcpi'], 's': ['hi2', 'hi1', 'eq', 'lo1', 'lo2']};
  const pre = {k: "t('sz305.k.'+id)", b: "t('sz305.b.'+id)", pt: "t('sz305.pt.'+p)", s: "t('sz305.p.s.'+lv"};
  for (const k of K) { const m = /^sz305\.(?:(k|b|pt)\.|p\.(s)\.)(\w+)$/.exec(k);
    if (m && ids[m[1] || m[2]].includes(m[3])) { assert.ok(c.includes(pre[m[1] || m[2]]), 'klucz składany w kodzie: ' + k); continue; }
    assert.ok(c.includes("'" + k + "'"), 'klucz w kodzie: ' + k); }
  for (const g of ['k', 'b', 'pt', 's']) for (const id of ids[g]) assert.ok(K.includes(g === 's' ? 'sz305.p.s.' + id : 'sz305.' + g + '.' + id), 'klucz dla ' + id);
});

test('v305g: miejsce w kodzie — funkcje bloku przed renderSu, blok przed stopką panelu, słuchacz i zegar za startem panelu; styl serii i telefon (siatka pulsu 2 kolumny); v321: bez widgetów TradingView', () => {
  const r0 = html.indexOf('function renderSu(){'), z0 = html.indexOf('/* ===================== v305g: SZLAKI');
  assert.ok(z0 > html.indexOf('/* ===================== v295g: SUROWCE') && z0 < r0, 'funkcje bloku w bloku panelu surowców, przed renderSu');
  assert.ok(html.includes("szBlk()+`<p class=\"pfoot\">${t('inst.file',{t:engDate(J.at)})} · ${t('su295g.foot')}"), 'blok tuż przed stopką panelu');
  const l0 = html.indexOf("document.addEventListener('click',e=>{const tg=e.target;if(tg&&tg.closest&&tg.closest('#g-surowce details#su-b-sz>summary'))szLoad();});");
  assert.ok(l0 > html.indexOf('\nsuLoad();suAuto();try{new MutationObserver') && l0 < html.indexOf('/* ===================== v98: USA — energia'), 'słuchacz bloku za startem panelu, przed blokiem USA');
  assert.ok(!su295.blk.includes('su-b-sz>summary') && !su295.blk.includes('szLoad(1)'), 'poza blokiem v295g — liczba słuchaczy i zegarów panelu bez zmian');
  assert.ok(sz305.lis.includes("document.addEventListener('click',") && sz305.lis.split('addEventListener(').length === 2, 'jeden słuchacz bloku');
  assert.ok(html.includes('setInterval(()=>{if(!document.hidden&&SZ.j)szLoad(1);},30*60*1000);'));
  assert.ok(html.includes('#g-surowce .wk-ch .sz-m{--k:var(--tl)}#g-surowce .wk-ch .sz-a{--k:var(--yl)}'), 'kolory linii metali i rolnych (bez zieleni i czerwieni)');
  assert.ok(html.includes('@media (max-width:620px){#g-surowce .su-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}'), 'telefon: kafle cieśnin w 2 kolumnach (siatka pulsu)');
  const sec = id => html.indexOf(`<section class="panel pcard" id="${id}" hidden></section>`);
  assert.ok(sec('g-surowce') > 0 && sec('tv-markets') < 0, 'v321: widgety TradingView usunięte');
  assert.ok(!sz305.code.includes('setTimeout') && !sz305.code.includes('localStorage'), 'bez zegarów i pamięci przeglądarki w bloku');
});

