  assert.ok(head.indexOf('<link href="fonts/fonts.css" rel="stylesheet">') > 0 && head.indexOf('<link href="fonts/fonts.css" rel="stylesheet">') < head.indexOf(P[0]), 'po arkuszu czcionek (najpierw style)');
