    const s0 = src.indexOf("<script>\n(function(){\n'use strict';\n");
    const MARK = src.slice(0, s0 > 0 ? s0 : src.length).replace(/<!--[\s\S]*?-->/g, '').replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
