  assert.ok(o2.includes('prm.k.cb.raw{"v":"<span class=\\"neg\\">−0.09 %</span>"}') && o2.includes('prm.k.cb.raw{"v":"<span class=\\"pos\\">+0.12 %</span>"}'), 'premia bez przeliczenia USDT — w kolorze znaku (dawniej szara)');
