    new Function('srvJSON', ...names, html.slice(a, b).replace(/\b(CMC|KR)\b/g, 'H') + '\n' + fn + '();')(() => (rej ? SP.reject(new Error('sieć')) : SP.resolve(resp)), ...stubs);
