  H = {data: OLD}; assert.deepEqual(one('cmcLoad', ['renderWhy', 'H', 'gOk', 'renderCmc', 'renderKPI', 'ldPonow', 'ldUdane'], H, {total_mcap: 2, at: 'y'}), ['ldUdane', 'gOk', 'renderCmc', 'renderWhy', 'renderKPI']);
