  assert.ok(html.includes("${t('inst.asof')} ${cftcD(m.asof)}${gAgeNote(m.asof)}${m.kept?' · '+t('cftc.kept'):''}`:t('eng.gap')}</summary>`+"), 'CFTC krypto: stan w stylu nagłówka panelu („6 paź 2026”)');
