  assert.equal(T[3].val, '16% obrotu spot', 'DEX 5,43 mld ÷ obrót spot 34,8 mld = 15,6%'); assert.ok(T[3].raw.includes('doba UTC wobec kroczących 24 h'));
  assert.ok(h.includes('<div class="gx-h"><b>Ten sam wskaźnik w czterech dobach</b></div>')); assert.ok(h.includes('09.09 — 30 dób wcześniej') && h.includes('02.10 — 7 dób wcześniej') && h.includes('08.10 — doba wcześniej') && h.includes('09.10 — ostatnia pełna doba'));
  const sieci = h.slice(h.indexOf('Podział wg sieci'), h.indexOf('Udział w obrocie DEX'));
  const S = [...sieci.matchAll(/<span class="gxs-n">([^<]*)<\/span><span class="gxs-b"><span class="gxs-t" aria-hidden="true"><i( class="\w+")? style="width:([\d.]+)%"><\/i><\/span><span class="gxs-v">([^<]*)<\/span>/g)].map(m => [m[1], +m[3], m[4]]);
  assert.equal(S.length, 11); assert.equal(S[0][0], 'Solana'); assert.ok(Math.abs(S[0][1] - 26.87) < 0.01 && S[0][2] === '26,9% · 70,0 mld USD', S[0].join('|')); assert.equal(S[10][0], 'pozostałe sieci');
  assert.ok(Math.abs(S.reduce((a, r) => a + r[1], 0) - 100) < 0.1, 'słupki = udziały, razem 100%');
  assert.ok(h.includes('DEX, doba 09.10 (UTC)') && h.includes('Giełdy scentralizowane (spot), kroczące 24 h do '), 'porównanie z giełdami'); assert.ok(h.includes('giełdy scentralizowane z notowaniami spot: 62'));
  assert.ok(h.includes('Największe protokoły DEX w ostatniej dobie') && h.includes('Uniswap V4')); assert.ok(h.includes('Udział w obrocie DEX z 30 dób do 9 paź 2026; sieci łącznie: ' + d.chains_n));
  /* bez pliku giełd: kafel i porównanie „—” / brak, reszta karty działa */
  const K2 = gx349.mk('pl', gx349.files(null)); K2.api.dxLoad(); const T2 = gx349.tiles(gx349.sp(K2.els['#c-dex'].innerHTML));
  assert.equal(T2[3].val, '—'); assert.ok(!K2.els['#c-dex'].innerHTML.includes('DEX, doba 09.10 (UTC)')); assert.equal(T2[0].val, '5,43 mld USD');
