  const OLD = gx349.clone(GX349_D); OLD.dex.day = '2026-10-04'; const KO = gx349.mk('pl', gx349.files(undefined, OLD)); KO.api.dxLoad(); assert.equal(KO.els['#c-dex'].hidden, true);
