  const m0 = html.indexOf('function instMld('), mSrc = html.slice(m0, html.indexOf('\nconst instSign', m0));
  assert.ok(f0 > 0 && f1 > f0 && e0 > 0 && m0 > 0, 'pomocnicze funkcje strony');
  const state = {T: Date.parse('2026-10-13T14:30:00Z')};
  class FD extends Date { constructor(...a) { if (a.length === 0) super(state.T); else super(...a); } static now() { return state.T; } }
  const clone = o => JSON.parse(JSON.stringify(o));
  const sp = h => String(h).replace(/\u00a0|\u202f/g, ' ');
