    const F = new Function('LANG', 'LOCALE', html.slice(f0, f1) + '\n' + eSrc + '\n' + mSrc + '\nreturn {nfmt, engNum, instMld};')(L, LOC);
    const calls = [], pend = [], rer = [], lis = [], errs = [];
    const srv = n => { calls.push(n); const v = (files || {})[n]; const r = v === undefined ? null : v === 'ERR' ? 'ERR' : clone(v);
      return {then(f, g) { const go = () => (r === 'ERR' ? g(new Error('x')) : f(r)); if (opt.async) pend.push(go); else go(); return this; }}; };
    const doc = {addEventListener: (e, f, c) => lis.push([e, f, c])};
