test('v357 ZRODLA3: okablowanie panelu — trzy bloki w kolejności (portfel Fed pod płynnością dolara, fundusze pod sekcją Fed, Eurosystem pod aktywami razem), moduł po znaczniku v355, pliki GLOBAL', () => {
  const r0 = html.indexOf('function renderInst(){'), r1 = html.indexOf('\n}\n', r0);
  const pos = s => { const i = html.indexOf(s, r0); assert.ok(i > r0 && i < r1, 'w renderInst: ' + s); assert.equal(html.split(s).length, 2, 'jedno wystąpienie: ' + s); return i; };
  const iA = pos("html+=typeof lqBlock==='function'?lqBlock('soma'):'';"), iA2 = pos('/* A2. Fed przez FRED'), iHf = pos("html+=typeof lqBlock==='function'?lqBlock('hf'):'';"), iB = pos('/* B. salda TARGET */');
  const iB2 = pos('/* B2. Eurosystem (EBC)'), iEbc = pos("html+=typeof lqBlock==='function'?lqBlock('ebc'):'';"), iB3 = pos('/* B3. bilans płatniczy strefy euro'), iA0 = pos('/* A. płynność dolara: TGA, RRP, SOMA */');
  assert.ok(iA0 < iA && iA < iA2 && iA2 < iHf && iHf < iB && iB < iB2 && iB2 < iEbc && iEbc < iB3, 'kolejność bloków w panelu');
  assert.ok(html.indexOf('/* v355: koniec */') < html.indexOf('/* ===================== v357 (zwiad 3): PŁYNNOŚĆ DOLARA'), 'moduł po znaczniku końca v355 (poza wycinkiem jego testów)');
  assert.ok(html.includes("const LQ_FILE={soma:'soma-sklad',ebc:'eurosystem',hf:'hedge'};"), 'trzy pliki');
  assert.equal(html.split('srvJSON(LQ_FILE[k])').length, 2, 'pliki czyta jedna funkcja (lqLoad)');
  assert.ok(!/SRV_GR=\{[^}]*(soma-sklad|eurosystem|hedge)/.test(html) && !/SRV_GR\.(hedge|eurosystem)/.test(html), 'to GLOBAL — nie grupa CRYPTO');
  assert.ok(html.includes("typeof lqBlock==='function'"), 'bezpiecznik typeof');
});

test('v357 ZRODLA3: ładowanie — plik dopiero przy pierwszym rysowaniu, komunikat „wczytuję”, błąd = komunikat (nigdy zero), ponowienie po 2 min, odświeżenie po 30 min, przerysowanie panelu po wczytaniu', () => {
  const K = lq357.mk('pl', lq357.files(), {async: true});
  assert.deepEqual(K.calls, [], 'przy starcie modułu nic nie jest pobierane');
  const h1 = lq357.sp(K.api.lqBlock('soma'));
  assert.deepEqual(K.calls, ['soma-sklad'], 'pierwsze rysowanie pobiera plik'); assert.ok(h1.includes('Portfel papierów Fed: z czego się składa') && h1.includes('Wczytuję dane'), h1);
  assert.ok(!/mld USD|6 360/.test(h1), 'bez liczb przed wczytaniem');
  K.api.lqBlock('soma'); K.api.lqBlock('soma'); assert.deepEqual(K.calls, ['soma-sklad'], 'trwające wczytanie nie rusza drugiego');
  K.flush(); assert.equal(K.rer.length, 3, 'po wczytaniu przerysowanie panelu (każde rysowanie czekało na wynik)');
  const h2 = lq357.sp(K.api.lqBlock('soma')); assert.ok(h2.includes('6 360,5 mld USD'), h2); assert.deepEqual(K.calls, ['soma-sklad'], 'z pamięci (30 min)');
  lq357.state.T += 29 * 60e3; K.api.lqBlock('soma'); assert.deepEqual(K.calls, ['soma-sklad'], 'po 29 min nadal z pamięci');
  lq357.state.T += 2 * 60e3; K.api.lqBlock('soma'); assert.equal(K.calls.length, 2, 'po 31 min odświeżenie'); K.flush();
  assert.ok(lq357.sp(K.api.lqBlock('soma')).includes('6 360,5'), 'rysujemy to, co jest');
  // błąd: brak pliku → komunikat, ponowienie dopiero po 2 min; potem poprawny plik
  lq357.state.T = Date.parse('2026-10-13T14:30:00Z');
  const E = lq357.mk('pl', {'soma-sklad': null, eurosystem: 'ERR', hedge: {v: 1}});
  for (const k of ['soma', 'ebc', 'hf']) { const h = lq357.sp(E.api.lqBlock(k)); assert.ok(h.includes('Dane chwilowo niedostępne') && !/\b0 mld/.test(h), k + ': ' + h); }
  assert.equal(E.calls.length, 3); E.api.lqBlock('soma'); assert.equal(E.calls.length, 3, 'w ciągu 2 min bez ponowienia');
  lq357.state.T += 2 * 60e3 + 1; E.api.lqBlock('soma'); assert.equal(E.calls.length, 4, 'po 2 min ponowienie');
  assert.equal(lq357.sp(E.api.lqBlock('nieznany')), '', 'nieznany blok — pusto');
  lq357.state.T = Date.parse('2026-10-13T14:30:00Z');
});

test('v357 ZRODLA3: walidacja plików — zła wersja, brak dnia, ostatni dzień ≠ dzień danych, wiersz z „null”, za mało punktów = plik odrzucony', () => {
  const K = lq357.mk('pl', lq357.files()), c = lq357.clone, A = K.api;
  assert.ok(A.lqOk('soma', LQ357_S) && A.lqOk('ebc', LQ357_E) && A.lqOk('hf', LQ357_H));
  for (const [k, J] of [['soma', LQ357_S], ['ebc', LQ357_E], ['hf', LQ357_H]]) {
    assert.ok(!A.lqOk(k, null) && !A.lqOk(k, []) && !A.lqOk(k, {}) && !A.lqOk(k, 'x'), k);
    assert.ok(!A.lqOk(k, Object.assign(c(J), {v: 2})), k + ': wersja'); assert.ok(!A.lqOk(k, Object.assign(c(J), {asof: '2026-13-40'})), k + ': dzień');
    assert.ok(!A.lqOk(k, Object.assign(c(J), {at: 'x'})), k + ': at'); assert.ok(!A.lqOk(k, Object.assign(c(J), {asof: '2026-10-01'})), k + ': ostatni dzień serii ≠ dzień danych');
  }
  const s = c(LQ357_S); s.d[10][3] = null; assert.ok(!A.lqOk('soma', s), 'null w wierszu portfela'); const s2 = c(LQ357_S); s2.d = s2.d.slice(-5); assert.ok(!A.lqOk('soma', s2), 'za mało tygodni');
  const s3 = c(LQ357_S); s3.peak = [null, 1]; assert.ok(!A.lqOk('soma', s3), 'szczyt');
  const e = c(LQ357_E); e.k.total[3] = ['2026-01-02', 'x']; assert.ok(!A.lqOk('ebc', e), 'tekst zamiast liczby'); const e2 = c(LQ357_E); delete e2.k.total; assert.ok(!A.lqOk('ebc', e2), 'brak sumy');
  const h = c(LQ357_H); h.d[2] = ['2025-01-01', 1]; assert.ok(!A.lqOk('hf', h), 'wiersz krótszy');
});

test('v357 ZRODLA3: formatowanie kwot, zmian i procentów — brak = „—”, poniżej 1 mln „<1 mln”, znak dopiero po zaokrągleniu, zero żółte, minus długi', () => {
  const A = lq357.mk('pl', lq357.files()).api, A2 = lq357.mk('en', lq357.files()).api, sp = lq357.sp;
  assert.equal(A.lqAmt(null, 'usd'), '—'); assert.equal(A.lqAmt(NaN, 'eur'), '—'); assert.equal(A.lqAmt(undefined, 'usd'), '—'); assert.equal(A.lqAmt('5', 'usd'), '—', 'tekst to nie liczba');
  assert.equal(A.lqAmt(0.4, 'usd'), '<1 mln USD'); assert.equal(A.lqAmt(-0.4, 'eur'), '<1 mln EUR'); assert.equal(A.lqAmt(0, 'usd'), '0,0 mld USD', 'prawdziwe zero to 0, nie brak');
  assert.equal(A.lqAmt(1234567, 'usd'), '1 234,6 mld USD'); assert.equal(A.lqAmt(999, 'eur'), '1,0 mld EUR'); assert.equal(sp(A2.lqAmt(6360520, 'usd')), '6,360.5 USD bn', 'angielski zapis liczb i jednostka (jednostka ze słownika panelu)');
  assert.equal(A.lqSig(-2060808, 'usd'), '−2 060,8 mld USD'); assert.equal(A.lqSig(250000, 'usd'), '+250,0 mld USD'); assert.equal(A.lqSig(40, 'usd'), '0 mld USD', 'poniżej 50 mln — bez znaku'); assert.equal(A.lqSig(-40, 'eur'), '0 mld EUR'); assert.equal(A.lqSig(null, 'usd'), '—');
  assert.equal(A.lqSig(60, 'usd'), '+0,1 mld USD'); assert.equal(A.lqSig(-60, 'usd'), '−0,1 mld USD'); assert.ok(A.lqSig(-5, 'usd').includes('−') === false, 'zaokrąglone do zera bez znaku');
  assert.equal(A.lqPct(-24.47), '−24,5%'); assert.equal(A.lqPct(3.04), '+3,0%'); assert.equal(A.lqPct(-0.0499), '−0,05%'); assert.equal(A.lqPct(0), '0%'); assert.equal(A.lqPct(0.0001), '0%', 'ułamek poniżej 0,005% to 0, bez znaku'); assert.equal(A.lqPct(null), '—');
  assert.equal(A.lqTone(0.04, 1), 'neu'); assert.equal(A.lqTone(-0.04, 1), 'neu'); assert.equal(A.lqTone(0.06, 1), 'pos'); assert.equal(A.lqTone(-0.06, 1), 'neg'); assert.equal(A.lqTone(null, 1), 'na'); assert.equal(A.lqTone(0.004, 2), 'neu'); assert.equal(A.lqTone(-0.04, 2), 'neg'); assert.equal(A.lqTone(0, 2), 'neu');
  assert.equal(A.lqChg(null, 'usd', 5), '<span class="na">—</span>'); assert.equal(A.lqChg(-60, 'usd', 6000), '<span class="neg">−0,1 mld USD (−1,0%)</span>'); assert.equal(A.lqChg(60, 'usd', 0), '<span class="pos">+0,1 mld USD</span>', 'baza zero — bez procentu, nie dzielenie przez zero');
  assert.equal(A.lqChg(40, 'usd', 6000), '<span class="neu">0 mld USD (+0,7%)</span>', 'zero żółte, procent policzony z tego samego zdarzenia');
  assert.ok(A.lqBar('x', 130, '1', 's').includes('width:100.0%') && A.lqBar('x', -5, '1', 's').includes('width:0.0%') && A.lqBar('x', null, '1', 's').includes('width:0.0%') && A.lqBar('x', 33.33, '1', 's').includes('width:33.3%'), 'szerokość słupka w 0–100%');
  // lqBack: najbliższy punkt w tolerancji, nigdy ostatni, brak = null
  const S = [['2026-01-01', 1], ['2026-01-08', 2], ['2026-01-15', 3], ['2026-01-22', 4]];
  assert.deepEqual(A.lqBack(S, 14, 2), ['2026-01-08', 2]); assert.deepEqual(A.lqBack(S, 15, 2), ['2026-01-08', 2]); assert.equal(A.lqBack(S, 40, 3), null); assert.equal(A.lqBack(S, 0, 3), null, 'ostatni punkt nie jest punktem odniesienia'); assert.equal(A.lqBack([], 7, 3), null); assert.equal(A.lqBack(null, 7, 3), null);
});

test('v357 ZRODLA3: portfel Fed — kafelki (razem, od szczytu, rok, 4 tygodnie), pięć grup z udziałami, wykres dwóch lat, tabela po rozwinięciu; kolory z pokazanej liczby, data i wiek', () => {
  const K = lq357.mk('pl', lq357.files()), sp = lq357.sp, txt = lq357.txt, D = LQ357_S.d, L = D[D.length - 1];
  const h = sp(K.api.lqBlock('soma')), T = txt(h);
  assert.ok(h.startsWith('<h3 class="mtxt">[f:us]<b>Portfel papierów Fed: z czego się składa</b></h3><p class="pnote">Fed trzyma papiery'), h.slice(0, 200));
  assert.ok(T.includes('Portfel razem 6 360,5 mld USD') && T.includes('stan 2026-10-07 · wiek(2026-10-07)'), 'kafel „razem” z dniem i wiekiem: ' + T);
  const kafel = (nazwa) => { const m = h.match(new RegExp('<span>' + nazwa + '</span><b[^>]*>(.*?)</b><small class="mtxt">(.*?)</small>')); assert.ok(m, nazwa); return m; };
  const ch = (v, base) => { const a = Math.abs(v), w = Math.floor(a / 1000), t10 = Math.round((a - w * 1000) / 100); return (v > 0 ? '+' : '−') + String(t10 === 10 ? w + 1 : w).replace(/\B(?=(\d{3})+(?!\d))/g, ' ') + ',' + (t10 === 10 ? 0 : t10) + ' mld USD (' + (v > 0 ? '+' : '−') + (Math.abs(v / base * 100)).toFixed(1).replace('.', ',') + '%)'; };
  const pk = LQ357_S.peak, dPk = L[1] - pk[1], m1 = kafel('Od szczytu');
  assert.equal(txt(m1[1]), ch(dPk, pk[1]), 'od szczytu'); assert.ok(m1[1].startsWith('<span class="neg">') && txt(m1[2]).includes('szczyt 2022-04-13: 8 421,3 mld USD'), m1[0]);
  const p52 = D.find(r => r[0] === '2025-10-08'), m2 = kafel('W ciągu roku');
  assert.equal(txt(m2[1]), ch(L[1] - p52[1], p52[1]), 'rok = punkt sprzed 364 dni'); assert.ok(m2[1].startsWith('<span class="neg">') && txt(m2[2]) === 'od 2025-10-08');
  const p4 = D.find(r => r[0] === '2026-09-09'), m3 = kafel('W ciągu 4 tygodni');
  assert.equal(txt(m3[1]), ch(L[1] - p4[1], p4[1])); assert.ok(txt(m3[2]) === 'od 2026-09-09');
  // pięć grup: nazwa, słupek (udział), kwota, udział i zmiana w roku
  const names = ['Obligacje i noty Skarbu USA', 'Papiery hipoteczne (MBS)', 'Bony skarbowe', 'Papiery indeksowane inflacją (TIPS)', 'Pozostałe'];
  const rows = [...h.matchAll(/<div class="secrow"><span class="sname"><span>(.*?)<\/span><\/span><span class="sbar b" aria-hidden="true"><i style="width:([\d.]+)%"><\/i><\/span><span class="sval ">(.*?)<\/span><span class="ssub"><span>(.*?)<\/span><\/span><\/div>/g)];
  assert.equal(rows.length, 5); assert.deepEqual(rows.map(r => r[1]), names);
  const sum = rows.reduce((a, r) => a + parseFloat(r[2]), 0); assert.ok(Math.abs(sum - 100) < 0.01, 'udziały sumują się do 100%: ' + sum);
  assert.equal(rows[0][3], '3 597,9 mld USD'); assert.ok(txt(rows[0][4]).startsWith('57 % portfela') || txt(rows[0][4]).startsWith('57% portfela'), txt(rows[0][4])); assert.ok(/rok <span class="neg">−/.test(rows[0][4]), 'zmiana w roku w kolorze znaku');
  assert.equal(rows[4][3], '29,8 mld USD'); assert.ok(txt(rows[4][4]).startsWith('0,5% portfela'), 'mały udział z miejscem po przecinku: ' + txt(rows[4][4]));
  // wykres i tabela
  assert.ok(h.includes('<svg class="lq-sp"') && h.includes('<polyline') && h.includes('aria-label="6 360,5 mld USD"'), 'wykres z opisem ostatniej wartości');
  assert.ok(h.includes('2024-10-09: ') && h.includes('2026-10-07: 6 360,5 mld USD'), 'podpis pierwszego i ostatniego punktu: ' + h.slice(h.indexOf('lq-spl'), h.indexOf('lq-spl') + 200));
  assert.ok(h.includes('<details class="etfd" id="lq357-soma"><summary>Ostatnie tygodnie (mln USD)</summary>'), 'tabela zwinięta'); const tr = h.slice(h.indexOf('lq357-soma')).match(/<tr><td>/g); assert.equal(tr.length, 8, '8 tygodni');
  assert.ok(h.includes('<td><span class="cell mono">2026-10-07</span></td><td><span class="cell mono">6 360 520</span></td>'), 'najnowszy tydzień w mln USD');
  const tb = h.slice(h.indexOf('lq357-soma')).match(/<tr><td><span class="cell mono">(\d{4}-\d{2}-\d{2})/g).map(x => x.slice(-10)); assert.deepEqual(tb, [...tb].sort().reverse(), 'tabela: najnowszy tydzień pierwszy'); assert.equal(tb[0], '2026-10-07');
  assert.ok(T.includes('Wartość nominalna bez wyrównania inflacyjnego papierów TIPS') && T.includes('Plik z D:2026-10-13T14:30:00+00:00'), 'notatka i czas pliku');
});

test('v357 ZRODLA3: portfel Fed — kierunek koloru po zaokrągleniu (wzrost zielony, spadek czerwony, zero żółte), brak punktu sprzed roku = „—” (nigdy zero), szczyt równy ostatniej wartości', () => {
  const c = lq357.clone, sp = lq357.sp;
  const S = c(LQ357_S); const P = S.d.find(r => r[0] === '2025-10-08'); const L = S.d[S.d.length - 1];
  // wzrost w roku: punkt sprzed roku mniejszy
  P[1] = L[1] - 250000; for (let i = 2; i < 7; i++) P[i] = Math.round(L[i] * 0.96);
  let h = sp(lq357.mk('pl', lq357.files(S)).api.lqBlock('soma'));
  assert.ok(/<span>W ciągu roku<\/span><b><span class="pos">\+250,0 mld USD \(\+4,1%\)<\/span><\/b>/.test(h), 'wzrost = zielony: ' + h.slice(h.indexOf('W ciągu roku'), h.indexOf('W ciągu roku') + 200));
  // zero po zaokrągleniu (zmiana poniżej 50 mln USD) = żółte „0”
  const Z = c(LQ357_S); Z.d.find(r => r[0] === '2025-10-08')[1] = Z.d[Z.d.length - 1][1] - 40;
  h = sp(lq357.mk('pl', lq357.files(Z)).api.lqBlock('soma'));
  assert.ok(/<span>W ciągu roku<\/span><b><span class="neu">0 mld USD \(0%\)<\/span><\/b>/.test(h), 'zero żółte, bez znaku: ' + h.slice(h.indexOf('W ciągu roku'), h.indexOf('W ciągu roku') + 200));
  // brak punktu sprzed roku (seria krótsza niż rok) i sprzed 4 tygodni: „—”, nigdy zero
  const N = c(LQ357_S); N.d = N.d.slice(-12);
  h = sp(lq357.mk('pl', lq357.files(N)).api.lqBlock('soma'));
  assert.ok(/<span>W ciągu roku<\/span><b>—<\/b><small class="mtxt">brak danych — to nie zero<\/small>/.test(h), 'rok: —'); assert.ok(!/<span>W ciągu 4 tygodni<\/span><b>—/.test(h), '4 tygodnie są w serii');
  assert.ok(!/W ciągu roku<\/span><b>(<span[^>]*>)?0/.test(h), 'brak ≠ zero'); assert.ok(/rok —/.test(h), 'zmiana grupy w roku bez punktu = „—”');
  // szczyt = ostatnia wartość: 0 (żółte)
  const Q = c(LQ357_S); Q.peak = [Q.asof, Q.d[Q.d.length - 1][1]];
  h = sp(lq357.mk('pl', lq357.files(Q)).api.lqBlock('soma'));
  assert.ok(/<span>Od szczytu<\/span><b><span class="neu">0 mld USD \(0%\)<\/span><\/b>/.test(h), 'na szczycie: 0 żółte');
});

test('v357 ZRODLA3: bilans Eurosystemu — kafelki z tygodniem i rokiem, aktywa i pasywa jako słupki udziału w sumie, wykres papierów QE, tabela, brak serii = „—”, notatka o złocie', () => {
  const K = lq357.mk('pl', lq357.files()), sp = lq357.sp, txt = lq357.txt, E = LQ357_E, T = E.k.total, L = T[T.length - 1];
  const h = sp(K.api.lqBlock('ebc')), X = txt(h);
  assert.ok(h.startsWith('<h3 class="mtxt">[f:eu]<b>Bilans Eurosystemu: z czego się składa</b></h3><p class="pnote">Eurosystem to system banków centralnych strefy euro.'), h.slice(0, 220));
  const kafel = nazwa => { const m = h.match(new RegExp('<span>' + nazwa + '</span><b[^>]*>(.*?)</b><small class="mtxt">(.*?)</small>')); assert.ok(m, nazwa); return m; };
  const m1 = kafel('Aktywa razem'); assert.equal(m1[1], '5 943,9 mld EUR'); assert.ok(txt(m1[2]).startsWith('stan 2026-10-09 · wiek(2026-10-09) (2026-W41) · tydzień '), txt(m1[2]));
  const w = T[T.length - 2], y = T.find(r => r[0] === '2025-10-10');
  assert.ok(m1[2].includes('tydzień <span class="neg">−3,0 mld EUR (−0,05%)</span>') && m1[2].includes('rok <span class="neg">−154,5 mld EUR (−2,5%)</span>'), 'zmiana tygodniowa i roczna w kolorze znaku: ' + m1[2] + ' ' + (L[1] - w[1]) + ' ' + (L[1] - y[1]));
  assert.equal(kafel('Papiery polityki pieniężnej')[1], '3 316,3 mld EUR'); assert.equal(kafel('Złoto')[1], '1 286,2 mld EUR'); assert.equal(kafel('Depozyty banków w banku centralnym')[1], '1 954,7 mld EUR');
  const rows = [...h.matchAll(/<div class="secrow"><span class="sname"><span>(.*?)<\/span><\/span><span class="sbar b" aria-hidden="true"><i style="width:([\d.]+)%"><\/i><\/span><span class="sval ">(.*?)<\/span><span class="ssub"><span>(.*?)<\/span><\/span><\/div>/g)];
  assert.equal(rows.length, 7); assert.deepEqual(rows.map(r => r[1]), ['Papiery kupione w ramach polityki pieniężnej (QE)', 'Złoto i należności w złocie', 'Pożyczki dla banków (operacje polityki pieniężnej)', 'Banknoty w obiegu',
    'Depozyty banków w banku centralnym (nadwyżka płynności)', 'Rachunki bieżące banków (rezerwa obowiązkowa)', 'Depozyty rządów strefy euro']);
  assert.ok(h.indexOf('Aktywa: co Eurosystem trzyma') < h.indexOf('Papiery kupione w ramach polityki pieniężnej (QE)') && h.indexOf('Pasywa: komu Eurosystem jest winien') < h.indexOf('Banknoty w obiegu'), 'dwie grupy');
  assert.equal(rows[0][3], '3 316,3 mld EUR'); assert.ok(/^56 % bilansu|^56% bilansu/.test(txt(rows[0][4])), txt(rows[0][4])); assert.equal(parseFloat(rows[0][2]).toFixed(1), (3316305 / 5943911 * 100).toFixed(1), 'szerokość słupka = udział w sumie');
  assert.ok(/tydzień <span class="neg">−/.test(rows[0][4]) && /rok <span class="neg">−/.test(rows[0][4]), 'papiery QE maleją: czerwone'); assert.equal(rows[2][3], '34,3 mld EUR'); assert.equal(rows[6][3], '94,7 mld EUR');
  assert.ok(h.includes('<svg class="lq-sp"') && h.includes('aria-label="3 316,3 mld EUR"') && h.includes('2025-09-19: ') && h.includes('2026-10-09: 3 316,3 mld EUR'), 'wykres 56 tygodni papierów QE');
  assert.ok(h.includes('<details class="etfd" id="lq357-ebc"><summary>Ostatnie tygodnie (mln EUR)</summary>') && h.slice(h.indexOf('lq357-ebc')).match(/<tr><td>/g).length === 8);
  assert.ok(h.includes('<td><span class="cell mono">2026-W41</span></td><td><span class="cell mono">2026-10-09</span></td><td><span class="cell mono">5 943 911</span></td><td><span class="cell mono">3 316 305</span></td><td><span class="cell mono">1 954 655</span></td>'), 'wiersz tabeli');
  assert.ok(X.includes('Złoto jest wyceniane po cenie rynkowej, więc jego zmiana to głównie zmiana ceny, nie zakupy.'), 'notatka o złocie');
  // seria bez ostatniego tygodnia (np. rzady) → „—” i „brak danych”, nigdy zero; seria z krótką historią (bez punktu sprzed roku) → zmiana roczna „—”
  const E2 = lq357.clone(E); E2.k.depozyty.pop(); E2.k.rzady = E2.k.rzady.slice(-8);
  const h2 = sp(lq357.mk('pl', lq357.files(undefined, E2)).api.lqBlock('ebc'));
  assert.ok(h2.includes('<span>Depozyty banków w banku centralnym</span><b>—</b><small class="mtxt">brak danych — to nie zero</small>'), 'kafel bez serii'); assert.ok(/Depozyty banków w banku centralnym \(nadwyżka płynności\)<\/span><\/span><span class="sbar b" aria-hidden="true"><i style="width:0.0%"><\/i><\/span><span class="sval ">—<\/span><span class="ssub"><span>brak danych — to nie zero<\/span>/.test(h2), 'słupek bez serii');
  assert.ok(/Depozyty rządów strefy euro[\s\S]*?rok —/.test(h2), 'krótka seria: rok „—”'); assert.ok(!/ 0,0 mld EUR/.test(h2.replace(/\+0,0|−0,0/g, '')), 'brak ≠ zero');
});

test('v357 ZRODLA3: fundusze hedgingowe — aktywa brutto i netto, dźwignia brutto, zmiana kwartał i rok z nazwanych punktów, dwa wykresy, tabela, wiek danych kwartalnych', () => {
  const K = lq357.mk('pl', lq357.files()), sp = lq357.sp, txt = lq357.txt, D = LQ357_H.d;
  const h = sp(K.api.lqBlock('hf')), X = txt(h);
  assert.ok(h.startsWith('<h3 class="mtxt">[f:us]<b>Fundusze hedgingowe w USA: ile kapitału i jaka dźwignia</b></h3><p class="pnote">Duże fundusze hedgingowe w USA zgłaszają regulatorowi swoje aktywa.'), h.slice(0, 220));
  const kafel = nazwa => { const m = h.match(new RegExp('<span>' + nazwa + '</span><b[^>]*>(.*?)</b><small class="mtxt">(.*?)</small>')); assert.ok(m, nazwa); return m; };
  const g = kafel('Aktywa brutto'); assert.equal(g[1], '13 863,0 mld USD'); assert.ok(txt(g[2]).startsWith('stan 2026-06-30 · wiek(2026-06-30) · kwartał: '), txt(g[2])); assert.ok(g[2].includes('<span class="pos">+1 084,0 mld USD (+8,5%)</span>'), g[2]);
  const n = kafel('Aktywa netto'); assert.equal(n[1], '5 511,0 mld USD'); assert.ok(n[2].includes('<span class="pos">+517,0 mld USD (+10,4%)</span>'), n[2]);
  const l = kafel('Dźwignia brutto'); assert.equal(l[1], '2,52×'); assert.ok(/kwartał: <span class="neg">−0,04×<\/span>/.test(l[2]), 'dźwignia spadła z 2,56× do 2,52×: ' + l[2]);
  const y = kafel('Aktywa brutto w ciągu roku'); assert.ok(y[1].includes('<span class="pos">+2 052,0 mld USD (+17,4%)</span>'), y[1]); assert.ok(txt(y[2]) === 'od 2025-06-30 · netto +968,0 mld USD (+21,3%)', txt(y[2]));
  assert.equal(h.split('<svg class="lq-sp"').length, 3, 'dwa wykresy'); assert.ok(h.includes('Aktywa brutto od 2013 roku') && h.includes('Dźwignia brutto (aktywa brutto ÷ netto, przybliżenie)'));
  assert.ok(h.includes('aria-label="2,52×"') && h.includes('aria-label="13 863,0 mld USD"'), 'opisy ostatnich wartości wykresów');
  const rows = h.slice(h.indexOf('lq357-hf')); assert.equal(rows.match(/<tr><td>/g).length, 8, '8 kwartałów (z 12 w pliku testowym)');
  assert.ok(rows.includes('<td><span class="cell mono">2026-06-30</span></td><td><span class="cell mono">13 863 000</span></td><td><span class="cell mono">5 511 000</span></td><td><span class="cell mono">2,52×</span></td>'), 'najnowszy kwartał pierwszy');
  assert.ok(X.includes('Dźwignia brutto to przybliżenie (nie oficjalny wskaźnik)') && X.includes('Plik z D:2026-10-13T14:30:00+00:00'), 'notatka');
  // dane starsze niż rok: brak punktu sprzed roku → „—”; mało kwartałów (8) wystarcza do pokazania bloku
  const H2 = lq357.clone(LQ357_H); H2.d = H2.d.slice(-8); H2.d.splice(0, 5); assert.ok(!lq357.mk('pl', lq357.files()).api.lqOk('hf', H2), 'poniżej 8 kwartałów plik odrzucony');
  const H3 = lq357.clone(LQ357_H); H3.d = H3.d.slice(-8);
  const h3 = sp(lq357.mk('pl', lq357.files(undefined, undefined, H3)).api.lqBlock('hf'));
  assert.ok(/<span>Aktywa brutto w ciągu roku<\/span><b>[^<]*<span class="pos">\+2 052,0 mld USD/.test(h3), 'rok jest (8 kwartałów obejmuje 2025-06-30)');
});

test('v357 ZRODLA3: 10 języków — bez kluczy w wyniku, liczby w zapisie języka widza, alfabety, kolory bez zmian; rozwinięcie tabel przeżywa przerysowanie, błąd bloku nie psuje reszty panelu', () => {
  const LG = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'];
  for (const lg of LG) {
    const K = lq357.mk(lg, lq357.files());
    for (const k of ['soma', 'ebc', 'hf']) {
      const h = lq357.sp(K.api.lqBlock(k)); assert.ok(h.length > 1500 && !/lq357\./.test(h) && !/undefined|NaN|\[object/.test(h), lg + ' ' + k + ': ' + h.slice(0, 120));
      assert.ok(/<svg class="lq-sp"/.test(h) && /<details class="etfd" id="lq357-/.test(h), lg + ' ' + k);
    }
  }
  const t = (lg, k) => lq357.txt(lq357.mk(lg, lq357.files()).api.lqBlock(k));
  assert.ok(t('en', 'soma').includes('Portfolio total 6,360.5') && t('de', 'soma').includes('Portfolio gesamt 6.360,5') && t('fr', 'ebc').includes('Total de l’actif 5') && t('ru', 'hf').includes('Валовые активы') && /[一-鿿]/.test(t('zh', 'soma')) && /[぀-ヿ]/.test(t('ja', 'hf')), 'zapis liczb i alfabety');
  assert.ok(/2,52×|2\.52×/.test(t('en', 'hf')) && t('de', 'hf').includes('2,52×'), 'dźwignia w zapisie języka');
  // rozwinięcie tabeli przeżywa przerysowanie; obce szczegóły ignorowane
  const K = lq357.mk('pl', lq357.files()), l = K.lis.filter(c => c[0] === 'toggle'); assert.equal(l.length, 1); assert.equal(l[0][2], true, 'toggle nie bąbelkuje — przechwytywanie');
  assert.ok(!lq357.sp(K.api.lqBlock('soma')).includes('id="lq357-soma" open'));
  l[0][1]({target: {id: 'lq357-soma', open: true}}); l[0][1]({target: {id: 'inny', open: true}}); l[0][1]({}); l[0][1](null);
  assert.ok(lq357.sp(K.api.lqBlock('soma')).includes('id="lq357-soma" open') && !lq357.sp(K.api.lqBlock('ebc')).includes('id="lq357-ebc" open'), 'stan rozwinięcia zapamiętany osobno dla każdego bloku');
  l[0][1]({target: {id: 'lq357-soma', open: false}}); assert.ok(!lq357.sp(K.api.lqBlock('soma')).includes(' open>'));
  // błąd w jednym bloku: pusty wynik i komunikat w konsoli, pozostałe bloki działają
  K.api.LQ.soma.j = {v: 1, at: '2026-10-13T14:30:00+00:00', asof: '2026-10-07', d: 'zepsute', peak: []}; K.api.LQ.soma.at = Date.now();
  assert.equal(K.api.lqBlock('soma'), ''); assert.equal(K.errs.length, 1); assert.ok(lq357.sp(K.api.lqBlock('hf')).includes('13 863,0 mld USD'), 'fundusze działają mimo błędu portfela');
});

test('v357 ZRODLA3: słownik w czystym JSON po linii for słownika, 10 języków, te same klucze i zmienne, tłumaczenia (nie kopie), bez nazw dostawców; kod modułu i CSS', () => {
  const mm = [...html.matchAll(/^for\(const l in (EXTRA\d+)\)if\(I18N\[l\]\)Object\.assign\(I18N\[l\],\1\[l\]\);$/gm)];
  const mine = mm.find(m => html.includes('const ' + m[1] + '={"pl":{"lq357.load"'));
  assert.ok(mine, 'słownik v357 ma własną linię for');
  const i0 = html.indexOf('const ' + mine[1] + '='), i1 = html.indexOf(';\nfor(const l in ' + mine[1] + ')', i0), D = JSON.parse(html.slice(i0 + ('const ' + mine[1] + '=').length, i1));
  assert.equal(html.split('const ' + mine[1] + '=').length, 2, 'jeden słownik o tym numerze'); assert.equal(html.split('for(const l in ' + mine[1] + ')').length, 2);
  assert.ok(html.slice(0, i0).trimEnd().endsWith('*/') && html.slice(html.lastIndexOf('\n', i0 - 2), i0).includes('v357'), 'komentarz nagłówkowy nad słownikiem');
  const LG = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja']; assert.deepEqual(Object.keys(D), LG);
  const keys = Object.keys(D.pl); assert.ok(keys.length >= 60 && keys.every(k => /^lq357\./.test(k)), 'tylko klucze v357: ' + keys.length);
  const ph = s => (s.match(/\{[a-z]+\}/g) || []).sort().join();
  for (const lg of LG) {
    assert.deepEqual(Object.keys(D[lg]), keys, lg + ': te same klucze w tej samej kolejności');
    for (const k of keys) { assert.ok(typeof D[lg][k] === 'string' && D[lg][k].trim(), lg + ' ' + k); assert.equal(ph(D[lg][k]), ph(D.pl[k]), lg + ' ' + k + ': zmienne'); }
  }
  for (const lg of LG.slice(1)) { const same = keys.filter(k => D[lg][k] === D.pl[k]); assert.ok(same.length <= 3, lg + ': tłumaczenia, nie kopie polskiego: ' + same.join()); }
  assert.ok(/[а-яё]/i.test(D.ru['lq357.soma.t']) && /[一-鿿]/.test(D.zh['lq357.soma.t']) && /[぀-ヿ]/.test(D.ja['lq357.soma.t']) && /portfolio/i.test(D.en['lq357.soma.t']), 'alfabety języków');
  const NAZWY = /NY Fed|New York|ECB|EBC|EZB|BCE\b|ЕЦБ|欧洲央行|OFR|Office of Financial|FINRA|Eurostat|Bundesbank|Treasury Fiscal|Fiscal Data|FRED|St\. Louis|MFW|IMF|BIS\b|CoinGecko|DefiLlama|Binance|Coinbase|Form PF/;
  for (const lg of LG) for (const k of keys) assert.ok(!NAZWY.test(D[lg][k]), 'zero nazw dostawców: ' + lg + ' ' + k);
  const code = lq357.code; assert.ok(!NAZWY.test(code), 'kod modułu bez nazw dostawców (także w komentarzach): ' + (code.match(NAZWY) || [''])[0]);
  assert.ok(!/\bdocument\.write\b|\beval\(|innerHTML\s*=\s*[^`'"]*\bj\./.test(code), 'bez niebezpiecznych wzorców'); assert.ok(!/localStorage|sessionStorage|fetch\(/.test(code), 'moduł nie czyta ani nie zapisuje pamięci przeglądarki, pliki tylko przez srvJSON');
  for (const r of ['#inst .lq-bars{margin:4px 0 8px;max-width:760px}', '#inst .sbar.b i{background:linear-gradient(90deg,rgba(var(--bl-rgb),.5),var(--bl))}', '#inst .lq-sp{display:block;width:100%;max-width:520px;height:64px;margin:4px 0 0}',
    '@media (max-width:620px){#inst .lq-bars .secrow{grid-template-columns:minmax(0,3fr) minmax(28px,1fr) auto}#inst .lq-spl{flex-wrap:wrap}}']) assert.ok(html.includes(r), r);
  assert.ok(!/class="[^"]*\bneg\b[^"]*"[^>]*>\s*—/.test(lq357.sp(lq357.mk('pl', lq357.files()).api.lqBlock('soma'))), 'brak liczby nie dostaje koloru kierunku');
});

/* ===================== v358 (audyt G11: GLOBAL) — zapis dat Aktywa, panel sald TARGET, „Ostatnia aktualizacja”, teksty (10 języków). Testy bez zegara i bez sieci. ===================== */
const v358 = (() => {
  const {cut, LOC, tk, num} = v336, LG = ['pl', 'en', 'de', 'es', 'fr', 'it', 'pt', 'ru', 'zh', 'ja'];
  const dictOf = key => {   /* słownik (JSON) z linią, w której występuje klucz — wszystkie 10 języków */
    const i = html.indexOf('"' + key + '":'), ls = html.lastIndexOf('\n', i) + 1, le = html.indexOf('\n', i), m = /^const (EXTRA\d+)=(\{.*\});$/.exec(html.slice(ls, le));
    assert.ok(m, 'słownik z kluczem ' + key); assert.equal(html.split('"' + key + '":').length, 11, key + ': dokładnie 10 języków'); return {name: m[1], D: JSON.parse(m[2])};
  };
  const NAZWY = /NY Fed|New York|ECB|EBC|EZB|BCE\b|ЕЦБ|欧洲央行|OFR|FINRA|Eurostat|Bundesbank|FRED|St\. Louis|IMF|BIS\b|CoinGecko|DefiLlama|Binance|Coinbase|Yahoo|Stooq|TradingView/;
  /* panel sald TARGET: kod wycinka (TG, tgOk, tgLoad, tgRows, tgbPanel) z zaślepką pobierania — plik podany wprost, bez sieci */
  const tgCode = cut('const TG={j:null', 'const tgMld=');
  const lista = [['DE', 1071765.29, 1037116.1], ['ES', -442554.69, -430474.26], ['IT', -344949.42, -331168.67], ['LU', 195149.05, 210952.65], ['FR', -181336.52, -182480.77], ['AT', -123507.04, -113780.32],
    ['BE', 106577.36, 119874.98], ['GR', -105423.93, -106788.65], ['PT', -89435.76, -88985.05], ['IE', 81764.53, 85068.88], ['NL', 62220.09, 36451.57], ['BG', 22198.39, 21264.66], ['LT', 16856.98, 17397.2],
    ['FI', 13665.3, 10311.23], ['CY', 13541.15, 13193.48], ['SI', 13082.21, 12919.67], ['MT', 3276.47, 2418.57], ['EE', 2002.43, 1790.52], ['LV', -5671.19, -6218.89], ['SK', -6179.53, -5440.7], ['HR', -9939.62, -10447.57]];
  const ym = k => { const d = new Date(Date.UTC(2025, 7 + k, 1)); return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0'); };   /* k = 0…12: 2025-08 … 2026-08 */
  const plik = () => { const k = {}; for (const [c, v, prev] of lista) { const s = []; for (let i = 0; i <= 12; i++) s.push([ym(i), i === 12 ? v : i === 11 ? prev : i === 0 ? Math.round(v * 90) / 100 : Math.round((prev + (v - prev) * i / 12) * 100) / 100]); k[c] = c === 'BG' ? s.slice(5) : s; }
    return {v: 1, at: '2026-10-13T15:00:00+00:00', asof: '2026-08', k, st: {}}; };
  const mkTg = (odp) => { const log = {render: 0, ask: 0};
    const F = new Function('srvJSON', 'renderInst', tgCode + '\nreturn {TG, TG_ISO, tgbPanel, tgbRr};')(() => { log.ask++; return {then: (ok, bad) => { if (odp === null) bad(new Error('x')); else ok(odp); }}; }, () => { log.render++; });
    return {F, log}; };
  const inst = (INSTd, tgbPanel, TG_ISO) => { const N = num('pl'), helpers = cut('function instMld(mln,dec){', '\nconst FRED={data:null};') + '\n' + cut('function instRow(label,value,exact,note){', '\nfunction instFoot(') + '\n' + v336.line('const engNum=');
    const ri = cut('function renderInst(){', '\n/* v96-gt: ikony w tabelach GLOBAL'), el = {innerHTML: '', hidden: true};
    new Function('$', 'INST', 'FRED', 'REZ', 'COF', 'engDate', 'spBlock', 'zagBlock', 'fredCustKpis', 'fredCustTable', 'INST_TGB', 'bopSum', 'bopMld', 'rezHtml', 'cofHtml', 't', 'escH', 'instFoot', 'nfmt', 'LANG', 'LOCALE', 'tgbPanel', 'bilCty', 'TG_ISO',
      helpers + '\n' + ri + '\nrenderInst();')(q => (q === '#inst' ? el : null), {data: INSTd, at: INSTd.at}, {data: null}, {data: null}, {data: null}, s => 'D(' + s + ')', () => '', () => '', () => '', () => '',
      ['DE', 'IT', 'ES', 'NL', 'FR', 'IE', 'PT', 'GR', 'LU'], () => null, v => String(v), () => '', () => '', tk, s => String(s), d => 'F(' + d + ')', N.nfmt, 'pl', LOC, tgbPanel, c => 'N:' + c, TG_ISO || {});
    return el.innerHTML; };
  return {cut, LOC, tk, num, LG, dictOf, NAZWY, tgCode, lista, plik, mkTg, inst};
})();

test('v358 (G11-1): Aktywa — dzień stablecoinów i szacunku akcji jak w sąsiednich wierszach („12 paź 2026”), nie RRRR-MM-DD; wiek zostaje; bez gFreshTxt (wycinki innych testów) — jak dotąd', () => {
  const NOW = Date.parse('2026-10-13T10:00:00Z'), now0 = Date.now; Date.now = () => NOW;
  try {
    const P = v96src.tFor('pl'), e0 = html.indexOf('const engDate=iso=>'), engDate = new Function('LOCALE', 'LANG', html.slice(e0, html.indexOf('\n', e0)) + '\nreturn engDate;')(v358.LOC, 'pl');
    const fgi = html.slice(html.indexOf('const fgIso=s=>'), html.indexOf('\n', html.indexOf('const fgIso=s=>'))), fgl = html.slice(html.indexOf('function fgLong(iso){'), html.indexOf('\n', html.indexOf('function fgLong(iso){')));
    const GF = new Function('t', 'engDate', 'LOCALE', 'LANG', fgi + '\n' + fgl + '\n' + html.slice(html.indexOf('function gAgeNote(fresh){'), html.indexOf('\nfunction gRenderKpi(){')) + '\nreturn {gAgeNote, gFreshTxt};')(P, engDate, v358.LOC, 'pl');
    const GL = {fx: null, irlt: {}, stab: null, est: {d: '2026-10-12', r: {eur: {v: 120}, jpn: {v: 60}, usa: {v: 250}}}};
    const KP = [{k: 'g.k.stab', v: 313, d: 1.26, fresh: '2026-10-12'}, {k: 'g.k.eq', v: 430, fresh: '2026-10-09'}];
    const g = pgEnv({GLIVE: GL, gStabDelta: () => [3.9, 1.26, 313], GKPI: KP, gAgeNote: GF.gAgeNote, gFreshTxt: GF.gFreshTxt, t: P}); g.f.renderAssets();
    const row = k => g.el.innerHTML.split('<tr>').find(r => r.includes(P(k))) || '';
    assert.ok(row('as.stab').includes('12 paź 2026') && row('as.stab').includes(' · dane sprzed 1 dnia'), 'stablecoiny: ' + row('as.stab'));
    assert.ok(row('as.eq').includes('szacunek wartości na 12 paź 2026'), 'akcje: ' + row('as.eq'));
    assert.ok(!/\d{4}-\d{2}-\d{2}/.test(g.el.innerHTML), 'w tabeli Aktywa nie ma dnia w zapisie RRRR-MM-DD: ' + (g.el.innerHTML.match(/.{0,50}\d{4}-\d{2}-\d{2}.{0,20}/) || [''])[0]);
    const g0 = pgEnv({GLIVE: GL, gStabDelta: () => [3.9, 1.26, 313], GKPI: KP}); g0.f.renderAssets();
    assert.ok(g0.el.innerHTML.includes('pg.daily · 2026-10-12') && g0.el.innerHTML.includes('a293g.k.est{"d":"2026-10-12"}'), 'bez gFreshTxt — jak dotąd (surowy dzień)');
    /* gEqNote (podpis kafla „Rynki akcji”): dzień szacunku w zapisie czytelnika */
    const n0 = html.indexOf('function gEqNote(EQ,fr){'), nSrc = html.slice(n0, html.indexOf('\nfunction renderAssets(', n0));
    const note2 = new Function('t', 'escH', 'gFreshTxt', nSrc + '\nreturn gEqNote;')((k, o) => k + (o ? JSON.stringify(o) : ''), v96src.escH, GF.gFreshTxt);
    assert.equal(note2({n: 11, v: 1, est: '2026-10-08'}, '2026-10-12'), 'a293g.k.est{"d":"8 paź 2026"}', 'podpis kafla: dzień szacunku jak w tabelach');
    assert.equal(note2({n: 11, v: 1, est: '2026-10-12'}, '2026-10-12T20:00:00.000Z'), 'a293g.k.est0', 'ten sam dzień — „szacunek wartości” bez drugiego zapisu dnia');
    assert.ok(html.includes("t('a293g.k.est',{d:escH(typeof gFreshTxt==='function'?gFreshTxt(EQ.est):EQ.est)})") && !html.includes("t('a293g.k.est',{d:escH(EQ.est)})"), 'kod: oba miejsca przez gFreshTxt');
    assert.ok(html.includes("(sdD?escH(typeof gFreshTxt==='function'?gFreshTxt(sdD):sdD)+gAgeNote(sdD):noD())"), 'kod: dzień stablecoinów przez gFreshTxt');
  } finally { Date.now = now0; }
});

test('v358 (G11-2): panel sald TARGET — 10 krajów o największych saldach na wierzchu (z Austrią i Belgią), reszta w rozwinięciu; do wczytania pliku i przy błędzie — 9 krajów z uwagą „wybrane kraje”', () => {
  const I = {at: '2026-10-10T20:00:00+00:00', tgb: {asof: '2026-08', q: {DE: [['2026-07', 1037116.1], ['2026-08', 1071765.29]], IT: [['2026-07', -331168.67], ['2026-08', -344949.42]]}}};
  const A = v358.mkTg(v358.plik()), P = A.F.tgbPanel();
  assert.ok(P && P.asof === '2026-08', 'plik sald TARGET wczytany');
  assert.deepEqual(P.top.map(r => r.c), ['DE', 'LU', 'BE', 'IE', 'PT', 'GR', 'AT', 'FR', 'IT', 'ES'], '10 największych (wartość bezwzględna), od wierzyciela do dłużnika — jest Austria i Belgia');
  assert.deepEqual(P.rest.map(r => r.c), ['NL', 'BG', 'LT', 'FI', 'CY', 'SI', 'MT', 'EE', 'LV', 'SK', 'HR'], 'pozostałe 11, tak samo posortowane');
  assert.equal(P.top[0].last[1], 1071765.29); assert.equal(P.top[0].last[0], '2026-08');
  assert.ok(Math.abs(P.top[0].d12 - 1071765.29 * 0.1) < 0.02, 'zmiana w 12 miesięcy to różnica względem sierpnia 2025 (tu 90% poziomu), nie miesiąca wcześniej: ' + P.top[0].d12); assert.ok(P.top.every(r => r.d12 != null) && P.rest.find(r => r.c === 'BG').d12 == null, 'BG ma za krótką historię — brak zmiany (null), nie zero');
  assert.equal(A.log.ask, 1, 'jedno pobranie'); assert.ok(A.log.render >= 1, 'po wczytaniu panel jest przerysowany');
  A.F.tgbPanel(); assert.equal(A.log.ask, 1, 'plik świeży (< 30 min) — bez drugiego pobrania');
  const h = v358.inst(Object.assign({}, I, {tgb: Object.assign({}, I.tgb, {asof: '2026-07'})}), A.F.tgbPanel, A.F.TG_ISO), body = h.slice(h.indexOf('inst.tgb.t'), h.indexOf('inst.tgb.unit'));
  assert.ok(!body.includes('inst.tgb.sel'), 'z pełną listą — bez uwagi o wybranych krajach');
  const top = body.slice(0, body.indexOf('<details')), det = body.slice(body.indexOf('<details'));
  assert.equal((top.match(/<tr><td>/g) || []).length, 10, '10 wierszy na wierzchu'); assert.equal((det.match(/<tr><td>/g) || []).length, 11, '11 w rozwinięciu');
  assert.ok(top.includes('N:AUT') && top.includes('N:BEL') && top.indexOf('inst.cc.DE') < top.indexOf('N:AUT') && !top.includes('inst.cc.NL') && det.includes('inst.cc.NL') && det.includes('N:BGR'), 'nazwy: dotychczasowe z inst.cc., nowe z nazwy kraju w języku widza');
  assert.ok(det.includes('inst.tgb.rest{"n":11}') && det.includes('id="inst-tgb-rest"'), 'rozwinięcie z licznikiem');
  assert.ok(/N:BGR[\s\S]*?<span class="cell mono">—<\/span><\/td><\/tr>/.test(det), 'BG: brak zmiany rocznej = „—”');
  assert.ok(h.includes('inst.asof') && h.includes('F(2026-08)') && !h.includes('F(2026-07)'), 'stopka: miesiąc pliku sald (nie pliku instytucji)');
  /* do czasu wczytania (zaślepka bez odpowiedzi) i przy błędzie: dotychczasowe kraje + uwaga */
  for (const odp of [null, {v: 2}, {v: 1, at: 'x', asof: '2026-08', k: {DE: [['2026-08', 1]]}}]) {
    const B = v358.mkTg(odp); assert.equal(B.F.tgbPanel(), null, 'plik zły albo za krótki (< 10 krajów) — brak listy pełnej');
    const h2 = v358.inst(I, B.F.tgbPanel); assert.ok(h2.includes('inst.tgb.sel') && !h2.includes('<details class="etfd" id="inst-tgb-rest"') && (h2.match(/<tr><td>/g) || []).length === 2, 'dotychczasowa tabela z uwagą: ' + h2.slice(h2.indexOf('inst.tgb.t'), h2.indexOf('inst.tgb.t') + 200));
    assert.ok(h2.includes('F(2026-08)'), 'stopka z miesiącem pliku instytucji');
  }
  assert.ok(v358.inst(I).includes('inst.tgb.sel'), 'bez funkcji tgbPanel (wycinki innych testów) — jak dotąd, z uwagą');
});

test('v358 (G11-2): tgbPanel — jedno oczekujące przerysowanie, bez pętli; panel w kodzie strony przed kartą regionu TARGET', () => {
  const cb = [], F = new Function('srvJSON', 'renderInst', v358.tgCode + '\nreturn {TG, tgbPanel, tgbRr};')(() => ({then: () => {}}), () => {});
  F.TG.busy = true; F.tgbPanel(); F.tgbPanel(); F.tgbPanel();
  assert.equal(F.TG.cb.filter(f => f === F.tgbRr).length, 1, 'wiele rysowań w trakcie pobierania — jedna kolejka przerysowania');
  assert.ok(html.indexOf('function tgbPanel(){') > html.indexOf('function tgRows(J){') && html.indexOf('function tgbPanel(){') < html.indexOf('const tgMld='), 'po tgRows, przed formatowaniem karty regionu');
  assert.ok(html.includes("const tgbA=typeof tgbPanel==='function'?tgbPanel():null;"), 'panel pyta o pełną listę tylko gdy funkcja istnieje');
});

test('v358 (G11-6): lewa kolumna „Ostatnia aktualizacja” — czas ostatniego przebiegu automatu z wiekiem; bez pliku stanu chwila pobrania z dopiskiem; brak obu — „—”', () => {
  const code = v358.cut('function gUpdTxt(){', 'function gUpdAt(){');
  const mk = (G, eng) => new Function('GLIVE', 'engDate', 'gAgeNote', 't', 'LOCALE', 'LANG', code + '\nreturn gUpdTxt;')(G, eng, s => ' · wiek(' + s + ')', v358.tk, {pl: 'pl-PL'}, 'pl');
  const E = s => 'D(' + s + ')', AT = '2026-10-13T16:46:56+00:00', TMS = Date.parse('2026-10-13T16:58:00Z');
  assert.equal(mk({meta: {at: AT}, tms: TMS}, E)(), 'D(' + AT + ') · wiek(' + AT + ')', 'z pliku stanu (nie z chwili pobrania w karcie), z wiekiem');
  for (const bad of [null, {}, {at: 5}, {at: 'wczoraj'}, {at: '2026-10-13'}, {at: '2026-13-45T99:99:00Z'}]) {
    const s = mk({meta: bad, tms: TMS}, E)(); assert.ok(s.endsWith(' · upd.br') && !s.includes('D('), 'zły albo brakujący plik stanu ' + JSON.stringify(bad) + ' → chwila pobrania z dopiskiem: ' + s);
  }
  assert.equal(mk({meta: null, tms: 0}, E)(), '—', 'brak obu — „—”, nigdy zmyślony czas'); assert.equal(mk({tms: 0}, E)(), '—');
  assert.ok(mk({meta: {at: AT}, tms: TMS}, undefined)().endsWith(' · upd.br'), 'bez engDate (wycinek) — chwila pobrania');
  assert.ok(html.includes("const u=$('[data-i18n=\"upd.v\"]');if(u)u.textContent=gUpdTxt();"), 'gRenderRefresh używa gUpdTxt');
  assert.ok(html.includes('try{updSrc();}catch(e){}try{gUpdAt();}catch(e){}try{srvStale();}catch(e){}') && html.includes("if(typeof gUpdAt==='function')gUpdAt();"), 'po wczytaniu pliku stanu i po zmianie języka (także na CRYPTO)');
});

test('v358 (G11-3/4/5/7): teksty w 10 językach — złoto Eurosystemu raz na kwartał, kolor zmiany = kierunek (zmienność), kopia strony w pamięci przeglądarki, średnia niezaokrąglonych składników; bez nazw dostawców', () => {
  const RE = {
    'lq357.ebc.note': [/raz na kwartał/, /once a quarter/, /einmal im Quartal/, /una vez por trimestre/, /une fois par trimestre/, /una volta a trimestre/, /uma vez por trimestre/, /раз в квартал/, /每季度/, /四半期に一度/],
    'zm352.read': [/kierunek.*nie ocenę/, /direction.*not a judgement/, /Richtung.*keine Bewertung/, /dirección.*no una valoración/, /sens.*pas un jugement/, /direzione.*non un giudizio/, /direção.*não um juízo/, /направление.*а не оценку/, /方向.*而不是好坏评价/, /方向.*評価ではありません/],
    'fg.meth.g': [/niezaokrąglonych.*o 1/, /unrounded.*by 1/, /ungerundeten.*um 1/, /sin redondear.*en 1/, /non arrondies.*de 1/, /non arrotondate.*di 1/, /sem arredondar.*em 1/, /неокруглённым.*на 1/, /未四舍五入.*相差 1/, /丸める前.*1だけ/],
  };
  for (const key in RE) { const {D} = v358.dictOf(key); v358.LG.forEach((lg, i) => { const s = D[lg][key]; assert.ok(RE[key][i].test(s), key + ' ' + lg + ': ' + s.slice(-200)); assert.ok(!v358.NAZWY.test(s), 'zero nazw dostawców: ' + key + ' ' + lg); }); }
  const ph = s => (s.match(/\{[a-z]+\}/g) || []).sort().join();
  for (const key of Object.keys(RE)) { const {D} = v358.dictOf(key); for (const lg of v358.LG) assert.equal(ph(D[lg][key]), ph(D.pl[key]), key + ' ' + lg + ': zmienne'); }
});

test('v358: nowy słownik (upd.br, inst.tgb.sel, inst.tgb.rest) — czysty JSON z własną linią for, 10 języków, te same zmienne, tłumaczenia (nie kopie), bez nazw dostawców', () => {
  const {name, D} = v358.dictOf('upd.br'), keys = ['upd.br', 'inst.tgb.sel', 'inst.tgb.rest'];
  assert.deepEqual(Object.keys(D), v358.LG); assert.equal(html.split('const ' + name + '=').length, 2, 'jeden słownik o tym numerze');
  assert.equal(html.split('\nfor(const l in ' + name + ')if(I18N[l])Object.assign(I18N[l],' + name + '[l]);').length, 2, 'własna linia for');
  const i0 = html.indexOf('const ' + name + '='); assert.ok(html.slice(0, i0).trimEnd().endsWith('*/') && html.slice(html.lastIndexOf('\n', i0 - 2), i0).includes('v358'), 'komentarz nagłówkowy');
  const ph = s => (s.match(/\{[a-z]+\}/g) || []).sort().join();
  for (const lg of v358.LG) { assert.deepEqual(Object.keys(D[lg]), keys, lg + ': klucze'); for (const k of keys) { assert.ok(typeof D[lg][k] === 'string' && D[lg][k].trim(), lg + ' ' + k); assert.equal(ph(D[lg][k]), ph(D.pl[k]), lg + ' ' + k); assert.ok(!v358.NAZWY.test(D[lg][k]), lg + ' ' + k); } }
  for (const lg of v358.LG.slice(1)) assert.equal(keys.filter(k => D[lg][k] === D.pl[k]).length, 0, lg + ': tłumaczenia, nie kopie polskiego');
  assert.ok(/[а-яё]/i.test(D.ru['upd.br']) && /[一-鿿]/.test(D.zh['upd.br']) && /[぀-ヿ]/.test(D.ja['upd.br']), 'alfabety języków');
  assert.equal(D.pl['inst.tgb.rest'], 'Pozostałe kraje ({n})');
});


