    const fire = () => mos.filter(m => m.tg === el).forEach(m => m.cb());
    const expand = () => { el.classList.s.add('zw-on'); el.classList.s.delete('zw'); fire(); };
    const collapse = () => { el.classList.s.add('zw-on'); el.classList.s.add('zw'); fire(); };
