  assert.equal(A.iwRef(rows, 20, 3), null, 'najbliższy wiersz sprzed celu jest dalej niż tolerancja → brak'); assert.equal(A.iwRef([['2026-02-04', 1]], 1, 6), null);
  const P = iw401.J().ar; P.buy = P.buy.slice(-12); const I = A.iwArInfo(P); assert.equal(I.s20, null); assert.equal(I.q5, null === I.q5 ? null : I.q5); assert.equal(I.okno, false, 'szereg zakupów nie sięga początku roku');
  const J = iw401.J(); J.ar.buy = J.ar.buy.slice(-12); const K2 = iw401.mk('pl', iw401.files(J), {open: true}); const T = iw401.tiles(K2.html());
